/* Generado por tools/build-games.js a partir de games/mecaquack/ — no editar a mano. */
DT.registerBuiltin("g_mecaquack", { entry: 'index.html', files: {"img/arbol.png":{"b64":"","type":"image/png"},"img/arbusto.png":{"b64":"","type":"image/png"},"img/ballena.png":{"b64":"","type":"image/png"},"img/bombon-mini.png":{"b64":"","type":"image/png"},"img/bombon.png":{"b64":"","type":"image/png"},"img/carbon.png":{"b64":"","type":"image/png"},"img/casa.png":{"b64":"","type":"image/png"},"img/cinematica1.png":{"b64":"","type":"image/png"},"img/cinematica2.png":{"b64":"","type":"image/png"},"img/cinematica3.png":{"b64":"","type":"image/png"},"img/cinematica4.png":{"b64":"","type":"image/png"},"img/pasto.png":{"b64":"","type":"image/png"},"img/pato.png":{"b64":"","type":"image/png"},"img/roca.png":{"b64":"","type":"image/png"},"img/sauce.png":{"b64":"","type":"image/png"},"img/tiburon.png":{"b64":"","type":"image/png"},"index.html":"<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Mecaquack</title>\n<!-- Mecaquack — Equipo Maravilla · Instituto Tecnológico Superior de Irapuato.\n     Adaptado a DivierteTEC: logros con el SDK, guardado de partida, guarida del jefe,\n     controles táctiles y corrección de errores. -->\n<style>\n@import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&family=Nunito:wght@400;700;800&display=swap');\n*{margin:0;padding:0;box-sizing:border-box;}\nbody{background:#000;overflow:hidden;width:100vw;height:100vh;font-family:'Nunito',sans-serif;}\ncanvas{display:block;}\n#gc{position:absolute;top:0;left:0;}\n#hud{position:absolute;top:0;left:0;width:100%;pointer-events:none;z-index:10;}\n#hud-top{display:flex;justify-content:space-between;align-items:flex-start;padding:10px 14px;gap:8px;flex-wrap:wrap;}\n.hp{background:rgba(10,10,30,0.88);border:2px solid rgba(255,200,0,0.4);border-radius:10px;padding:8px 12px;color:white;font-size:11px;}\n.ht{font-family:'Press Start 2P',monospace;font-size:6px;color:#f39c12;margin-bottom:4px;letter-spacing:1px;}\n.hpbar{width:110px;height:9px;background:#333;border-radius:4px;overflow:hidden;margin-top:3px;}\n.hpf{height:100%;background:linear-gradient(90deg,#27ae60,#2ecc71);border-radius:4px;transition:width .3s;}\n.itag{background:rgba(255,200,0,0.12);border:1px solid rgba(255,200,0,0.35);border-radius:5px;padding:2px 6px;font-size:10px;color:#f9e079;}\n#techbar{position:absolute;bottom:36px;left:50%;transform:translateX(-50%);display:flex;gap:8px;pointer-events:none;z-index:10;}\n.ts{background:rgba(10,10,30,0.88);border:2px solid rgba(255,255,255,0.15);border-radius:10px;padding:6px 10px;text-align:center;color:#444;font-size:9px;min-width:62px;transition:all .3s;}\n.ts.unlocked{border-color:rgba(255,200,0,0.7);color:#fff;}\n.ts .tk{font-family:'Press Start 2P',monospace;font-size:6px;color:#f39c12;display:block;margin-bottom:2px;}\n.ts .ti{font-size:18px;display:block;}\n.ts .tn{font-size:8px;display:block;margin-top:1px;}\n#ilabel{position:absolute;top:46%;left:50%;transform:translate(-50%,-50%);font-family:'Press Start 2P',monospace;font-size:13px;color:#fff;text-shadow:0 0 20px #f39c12,2px 2px 0 #000;pointer-events:none;opacity:0;transition:opacity .5s;z-index:20;}\n#chint{position:absolute;bottom:8px;left:50%;transform:translateX(-50%);background:rgba(10,10,30,0.8);border:1px solid rgba(255,255,255,0.12);border-radius:7px;padding:5px 12px;color:rgba(255,255,255,0.45);font-size:9px;pointer-events:none;}\n.ov{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;z-index:50;background:rgba(0,0,0,0.87);}\n.ov.hidden{display:none;}\n.ob{background:linear-gradient(135deg,#0a0a1e,#1a1a3e);border:2px solid #f39c12;border-radius:18px;padding:28px 32px;text-align:center;color:white;max-width:560px;width:92%;box-shadow:0 0 60px rgba(243,156,18,0.22);max-height:92vh;overflow-y:auto;}\n.ob h2{font-family:'Press Start 2P',monospace;font-size:clamp(10px,2.5vw,16px);color:#f39c12;line-height:1.6;margin-bottom:8px;}\n.ob p,.ob li{font-size:12px;color:#ccc;margin:5px 0;line-height:1.75;}\n.btn{background:linear-gradient(135deg,#f39c12,#e67e22);color:white;border:none;padding:11px 24px;border-radius:22px;font-family:'Press Start 2P',monospace;font-size:9px;cursor:pointer;margin:6px 3px;box-shadow:0 4px 0 #c0392b;transition:all .1s;letter-spacing:.8px;}\n.btn:hover{transform:translateY(-2px);box-shadow:0 6px 0 #c0392b;}\n.btn:active{transform:translateY(2px);box-shadow:0 2px 0 #c0392b;}\n.btn.sec{background:linear-gradient(135deg,#2980b9,#1a6fa8);box-shadow:0 4px 0 #1a5276;}\n.btn.sec:hover{box-shadow:0 6px 0 #1a5276;}\n.btn.grn{background:linear-gradient(135deg,#27ae60,#229954);box-shadow:0 4px 0 #1a7a43;}\n.btn.grn:hover{box-shadow:0 6px 0 #1a7a43;}\n.btn.pur{background:linear-gradient(135deg,#8e44ad,#7d3c98);box-shadow:0 4px 0 #6c3483;}\n.btn.pur:hover{box-shadow:0 6px 0 #6c3483;}\n.btn:disabled{opacity:.4;cursor:not-allowed;transform:none;box-shadow:none;}\n.theory-box{background:rgba(255,255,255,0.05);border:1px solid rgba(255,200,0,0.3);border-radius:12px;padding:14px;margin:10px 0;text-align:left;}\n.theory-box h3{color:#f39c12;font-size:11px;margin-bottom:8px;font-weight:800;}\n.theory-box p,.theory-box li{font-size:11px;color:#ddd;line-height:1.8;}\n.theory-box ul{padding-left:16px;}\n.fml{display:inline-block;background:rgba(255,200,0,0.1);border:1px solid rgba(255,200,0,0.4);border-radius:5px;padding:2px 9px;font-family:monospace;font-size:13px;color:#f9e079;margin:2px 2px;}\n.ch-step{display:none;} .ch-step.vis{display:block;}\n.fopts{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:10px 0;}\n.fopt{background:rgba(255,255,255,0.07);border:2px solid rgba(255,255,255,0.2);border-radius:8px;padding:10px;cursor:pointer;font-size:11px;color:#eee;transition:all .2s;text-align:left;}\n.fopt:hover{border-color:#f39c12;background:rgba(255,200,0,0.08);}\n.fopt.correct{border-color:#4caf50;background:rgba(76,175,80,0.2);color:#4caf50;}\n.fopt.wrong{border-color:#e74c3c;background:rgba(231,76,60,0.2);color:#e74c3c;}\n.seq-bank{display:flex;flex-wrap:wrap;gap:7px;min-height:42px;padding:8px;background:rgba(0,0,0,0.3);border:2px dashed rgba(255,200,0,0.3);border-radius:10px;margin:6px 0;align-items:center;}\n.seq-drop{display:flex;flex-wrap:wrap;gap:7px;min-height:42px;padding:8px;background:rgba(76,175,80,0.05);border:2px dashed rgba(76,175,80,0.4);border-radius:10px;margin:6px 0;align-items:center;}\n.seq-drop.dragover{background:rgba(76,175,80,0.14);border-color:#4caf50;}\n.sitem{background:rgba(255,200,0,0.1);border:2px solid rgba(255,200,0,0.45);border-radius:8px;padding:7px 11px;cursor:grab;font-size:11px;color:#fff;user-select:none;transition:all .2s;}\n.sitem:hover{background:rgba(255,200,0,0.22);transform:scale(1.04);}\n.sitem.placed{background:rgba(76,175,80,0.15);border-color:#4caf50;cursor:default;}\n.match-row{display:flex;gap:10px;margin:6px 0;}\n.match-col{flex:1;display:flex;flex-direction:column;gap:6px;}\n.mh{font-size:8px;color:#888;text-align:center;font-family:'Press Start 2P',monospace;margin-bottom:2px;}\n.mitem{background:rgba(255,255,255,0.06);border:2px solid rgba(255,255,255,0.18);border-radius:8px;padding:8px;font-size:10px;color:#eee;text-align:center;cursor:pointer;transition:all .2s;min-height:36px;display:flex;align-items:center;justify-content:center;}\n.mitem:hover{border-color:#f39c12;}\n.mitem.sel{border-color:#2196f3;background:rgba(33,150,243,0.15);}\n.mitem.matched{border-color:#4caf50;background:rgba(76,175,80,0.12);cursor:default;}\n.mitem.flash{border-color:#e74c3c;background:rgba(231,76,60,0.15);}\n.craft-area{display:flex;gap:14px;margin:12px 0;align-items:flex-start;flex-wrap:wrap;justify-content:center;}\n.pbin{background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.12);border-radius:10px;padding:10px;min-width:130px;}\n.pbin h3{font-size:8px;color:#aaa;margin-bottom:6px;font-family:'Press Start 2P',monospace;}\n.pitem{background:rgba(255,200,0,0.1);border:2px solid rgba(255,200,0,0.3);border-radius:7px;padding:7px;margin:3px 0;cursor:grab;text-align:center;font-size:18px;transition:all .2s;user-select:none;}\n.pitem:hover{background:rgba(255,200,0,0.22);transform:scale(1.04);}\n.pitem.used{opacity:.3;cursor:not-allowed;filter:grayscale(1);}\n.blueprint{background:rgba(0,0,0,0.38);border:2px dashed rgba(255,200,0,0.4);border-radius:10px;padding:12px;min-width:170px;min-height:190px;}\n.blueprint h3{font-size:8px;color:#f39c12;margin-bottom:6px;font-family:'Press Start 2P',monospace;text-align:center;}\n.dslot{background:rgba(255,255,255,0.03);border:2px dashed rgba(255,255,255,0.18);border-radius:7px;padding:9px;margin:4px 0;text-align:center;font-size:10px;color:#555;min-height:42px;display:flex;align-items:center;justify-content:center;transition:all .2s;}\n.dslot.dragover{border-color:#f39c12;background:rgba(255,200,0,0.08);}\n.dslot.filled{border-color:#4caf50;background:rgba(76,175,80,0.1);color:#4caf50;font-size:17px;}\n#notif{position:absolute;top:68px;right:12px;background:linear-gradient(135deg,#1a1a3e,#0d2745);border:2px solid #f39c12;border-radius:11px;padding:9px 14px;color:white;font-size:11px;font-weight:700;z-index:80;opacity:0;transform:translateX(110%);transition:all .3s;pointer-events:none;max-width:240px;}\n#notif.show{opacity:1;transform:translateX(0);}\n#timer-bar{position:absolute;top:54px;left:50%;transform:translateX(-50%);background:rgba(10,10,30,0.9);border:2px solid #e74c3c;border-radius:8px;padding:5px 14px;color:#fff;font-size:11px;font-weight:700;z-index:75;display:none;pointer-events:none;}\n#timer-inner{display:inline-block;color:#e74c3c;font-family:'Press Start 2P',monospace;font-size:10px;}\n/* Shop */\n.shop-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:10px 0;}\n.shop-item{background:rgba(255,255,255,0.05);border:2px solid rgba(255,255,255,0.18);border-radius:10px;padding:10px 6px;text-align:center;cursor:pointer;transition:all .2s;}\n.shop-item:hover{border-color:#f39c12;background:rgba(255,200,0,0.08);}\n.shop-item.owned{border-color:#4caf50;background:rgba(76,175,80,0.1);}\n.shop-item .si-icon{font-size:24px;display:block;margin-bottom:4px;}\n.shop-item .si-name{font-size:9px;color:#eee;display:block;margin-bottom:3px;}\n.shop-item .si-cost{font-size:8px;color:#f39c12;font-family:'Press Start 2P',monospace;}\n.shop-tabs{display:flex;gap:6px;margin-bottom:10px;justify-content:center;}\n.shop-tab{background:rgba(255,255,255,0.07);border:2px solid rgba(255,255,255,0.2);border-radius:8px;padding:6px 12px;cursor:pointer;font-size:10px;color:#aaa;transition:all .2s;}\n.shop-tab.active{border-color:#f39c12;color:#fff;background:rgba(255,200,0,0.1);}\n/* Wardrobe */\n.wd-layout{display:flex;gap:14px;align-items:flex-start;justify-content:center;flex-wrap:wrap;}\n.wd-equip{display:flex;flex-direction:column;gap:8px;min-width:100px;}\n.wd-eslot{background:rgba(0,0,0,0.4);border:2px dashed rgba(255,200,0,0.4);border-radius:8px;padding:10px;text-align:center;min-height:58px;font-size:10px;color:#666;cursor:pointer;transition:all .2s;}\n.wd-eslot.has-item{border-color:#4caf50;background:rgba(76,175,80,0.1);color:#eee;}\n.wd-eslot .eslot-icon{font-size:22px;display:block;margin-bottom:2px;}\n.wd-eslot .eslot-label{font-size:7px;font-family:'Press Start 2P',monospace;color:#f39c12;display:block;}\n.wd-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;}\n.wd-cell{background:rgba(255,255,255,0.05);border:2px solid rgba(255,255,255,0.18);border-radius:7px;padding:8px;text-align:center;font-size:20px;min-height:46px;cursor:pointer;transition:all .2s;display:flex;align-items:center;justify-content:center;}\n.wd-cell:hover{border-color:#f39c12;background:rgba(255,200,0,0.08);}\n.wd-cell.equipped{border-color:#4caf50;background:rgba(76,175,80,0.15);}\n.wd-preview{width:80px;height:80px;background:rgba(0,0,0,0.4);border:2px solid rgba(255,200,0,0.3);border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:40px;position:relative;}\n/* diff selector */\n.diff-opts{display:flex;gap:10px;justify-content:center;margin:10px 0;flex-wrap:wrap;}\n.diff-opt{background:rgba(255,255,255,0.07);border:2px solid rgba(255,255,255,0.22);border-radius:10px;padding:12px 16px;cursor:pointer;text-align:center;transition:all .2s;min-width:90px;}\n.diff-opt:hover{transform:translateY(-3px);}\n.diff-opt.d1{border-color:#27ae60;}\n.diff-opt.d1:hover{background:rgba(39,174,96,0.15);}\n.diff-opt.d2{border-color:#f39c12;}\n.diff-opt.d2:hover{background:rgba(243,156,18,0.15);}\n.diff-opt.d3{border-color:#e74c3c;}\n.diff-opt.d3:hover{background:rgba(231,76,60,0.15);}\n.diff-opt .do-icon{font-size:22px;display:block;margin-bottom:4px;}\n.diff-opt .do-name{font-size:8px;font-family:'Press Start 2P',monospace;display:block;margin-bottom:3px;}\n.diff-opt .do-stars{font-size:10px;color:#f9e079;display:block;}\n#touch-ui{display:none;}\nbody.touch #touch-ui{display:block;}\nbody.touch #chint{display:none;}\nbody.touch #techbar{bottom:22px;gap:5px;pointer-events:auto;}\nbody.touch .ts{min-width:44px;padding:4px 6px;}\nbody.touch .ts .tn{display:none;}\n@media (max-width:700px){body.touch #techbar{bottom:160px;}}\nbody.touch .ts{pointer-events:auto;}\n#joy{position:absolute;left:24px;bottom:24px;width:120px;height:120px;border-radius:50%;background:rgba(255,255,255,0.08);border:2px solid rgba(255,200,0,0.4);z-index:30;touch-action:none;}\n#joy-knob{position:absolute;left:35px;top:35px;width:50px;height:50px;border-radius:50%;background:rgba(243,156,18,0.7);pointer-events:none;}\n#tbtns{position:absolute;right:18px;bottom:24px;display:grid;grid-template-columns:repeat(3,56px);gap:10px;z-index:30;}\n#tbtns button{width:56px;height:56px;border-radius:50%;border:2px solid rgba(255,200,0,0.5);background:rgba(10,10,30,0.8);color:#fff;font:700 18px Nunito,sans-serif;touch-action:none;}\n@keyframes goFall{0%{transform:rotate(0) scale(1);opacity:1;}100%{transform:rotate(-90deg) scale(.55);opacity:.35;}}\n</style>\n</head>\n<body>\n<canvas id=\"gc\"></canvas>\n<div id=\"hud\">\n  <div id=\"hud-top\">\n    <div class=\"hp\">\n      <div class=\"ht\">MECAQUACK</div>\n      <div style=\"font-size:10px;\">Vida: <span id=\"hv\">100</span>/100</div>\n      <div class=\"hpbar\"><div class=\"hpf\" id=\"hf\" style=\"width:100%\"></div></div>\n      <div style=\"margin-top:3px;font-size:9px;color:#aaa;\" id=\"dst\">Sin dron-mochila</div>\n    </div>\n    <div class=\"hp\">\n      <div class=\"ht\">INVENTARIO</div>\n      <div style=\"display:flex;gap:5px;margin-top:3px;flex-wrap:wrap;\" id=\"invrow\"><span style=\"color:#555;font-size:9px;\">vacio</span></div>\n    </div>\n    <div class=\"hp\">\n      <div class=\"ht\">PROGRESO</div>\n      <div style=\"font-size:10px;\">Estrellas: <span id=\"sv\">0</span> ⭐</div>\n      <div style=\"font-size:9px;color:#aaa;\">Retos: <span id=\"dv\">0</span>/19</div>\n      <div style=\"font-size:9px;color:#aaa;\">Tiburones: <span id=\"kv\">0</span></div>\n    </div>\n  </div>\n</div>\n<div id=\"techbar\">\n  <div class=\"ts\" id=\"ts-central\"><span class=\"tk\">[Q]</span><span class=\"ti\">&#x1f6e1;&#xfe0f;</span><span class=\"tn\">Archiparalelo</span></div>\n  <div class=\"ts\" id=\"ts-volcano\"><span class=\"tk\">[F]</span><span class=\"ti\">&#x1f525;</span><span class=\"tn\">Metalandia</span></div>\n  <div class=\"ts\" id=\"ts-mountain\"><span class=\"tk\">[G]</span><span class=\"ti\">&#x1faa8;</span><span class=\"tn\">Terralita</span></div>\n  <div class=\"ts\" id=\"ts-swamp\"><span class=\"tk\">[H]</span><span class=\"ti\">&#x1faa4;</span><span class=\"tn\">Pantanórbita</span></div>\n  <div class=\"ts\" id=\"ts-clouds\"><span class=\"tk\">[T]</span><span class=\"ti\">&#x1f300;</span><span class=\"tn\">Ventilandia</span></div>\n</div>\n<div id=\"ilabel\"></div>\n<div id=\"timer-bar\">Tiempo: <span id=\"timer-inner\">--</span>s</div>\n<div id=\"chint\">WASD mover &nbsp;|&nbsp; ESPACIO espada &nbsp;|&nbsp; E interactuar &nbsp;|&nbsp; B dron &nbsp;|&nbsp; V guardarropa &nbsp;|&nbsp; Q/F/G/H/T tecno</div>\n\n<!-- TITLE -->\n<div class=\"ov\" id=\"title-scr\">\n  <div class=\"ob\">\n    <h2>MECAQUACK</h2>\n    <p style=\"font-size:20px;margin:6px 0;\">&#x1f986; &#x2699;&#xfe0f; &#x1f30a;</p>\n    <p>Explora el archipielago ampliado, resuelve retos de ingenieria con dificultad escalable y derrota tiburones. Visita la Mercaquack para gastar estrellas en cosmeticos.</p>\n    <br>\n    <button class=\"btn grn\" id=\"btn-continue\" onclick=\"continueGame()\" style=\"display:none;\">CONTINUAR</button>\n    <button class=\"btn\" onclick=\"newGame()\">NUEVA PARTIDA</button>\n    <br><br>\n    <button class=\"btn sec\" onclick=\"skipToBoss()\" style=\"font-size:10px;padding:6px 18px;\">&#x2620; PRÁCTICA CONTRA EL JEFE</button>\n    <p style=\"font-size:10px;color:#e8a0a0;margin-top:8px;\">Completa 10 retos para abrir la guarida de Bombón en Selvarrón.</p>\n    <br><br>\n    <p style=\"font-size:9px;color:#555;\">WASD mover &middot; ESPACIO espada &middot; E interactuar &middot; B dron &middot; V guardarropa</p>\n  </div>\n</div>\n\n<!-- DRONE -->\n<div class=\"ov hidden\" id=\"drone-scr\" style=\"z-index:60;\">\n  <div class=\"ob\">\n    <h2 style=\"font-size:12px;\">DRON-MOCHILA</h2>\n    <p>Arrastra cada pieza a su ranura para ensamblarlo.</p>\n    <div class=\"craft-area\">\n      <div class=\"pbin\"><h3>PIEZAS</h3><div id=\"plist\"></div></div>\n      <div class=\"blueprint\" id=\"bp\" ondragover=\"event.preventDefault();document.getElementById('bp').classList.add('dragover')\" ondragleave=\"document.getElementById('bp').classList.remove('dragover')\" ondrop=\"dropBP(event)\">\n        <h3>PLANO</h3>\n        <div id=\"slarea\"></div>\n        <div style=\"font-size:9px;color:#aaa;text-align:center;margin-top:5px;\" id=\"cprog\">0/4 piezas</div>\n      </div>\n    </div>\n    <div id=\"cmsg\" style=\"font-size:10px;color:#aaa;min-height:16px;\"></div><br>\n    <button class=\"btn\" id=\"bassemble\" onclick=\"assembleDrone()\" disabled>ENSAMBLAR</button>\n    <button class=\"btn sec\" onclick=\"closeDrone()\">VOLVER</button>\n  </div>\n</div>\n\n<!-- CHALLENGE -->\n<div class=\"ov hidden\" id=\"ch-scr\" style=\"z-index:70;\">\n  <div class=\"ob\" style=\"max-width:570px;\">\n    <div class=\"ch-step\" id=\"ch-diff\">\n      <h2 id=\"ch-d-title\" style=\"font-size:11px;margin-bottom:6px;\"></h2>\n      <p style=\"font-size:11px;color:#aaa;\">Selecciona la dificultad del reto:</p>\n      <div class=\"diff-opts\">\n        <div class=\"diff-opt d1\" onclick=\"selectDiff(1)\">\n          <span class=\"do-icon\">&#x1f4d6;</span>\n          <span class=\"do-name\">FACIL</span>\n          <span class=\"do-stars\">x1 &#x2b50;</span>\n        </div>\n        <div class=\"diff-opt d2\" onclick=\"selectDiff(2)\">\n          <span class=\"do-icon\">&#x1f4aa;</span>\n          <span class=\"do-name\">NORMAL</span>\n          <span class=\"do-stars\">x1.5 &#x2b50; | 45s</span>\n        </div>\n        <div class=\"diff-opt d3\" onclick=\"selectDiff(3)\">\n          <span class=\"do-icon\">&#x1f480;</span>\n          <span class=\"do-name\">DIFICIL</span>\n          <span class=\"do-stars\">x2 &#x2b50; | 25s</span>\n        </div>\n      </div>\n      <button class=\"btn sec\" onclick=\"closeChallenge()\">CANCELAR</button>\n    </div>\n    <div class=\"ch-step\" id=\"ch-theory\">\n      <h2 id=\"ch-t-title\" style=\"font-size:12px;\"></h2>\n      <div class=\"theory-box\" id=\"ch-t-body\"></div>\n      <button class=\"btn grn\" onclick=\"goToChallenge()\">ENTENDIDO - IR AL RETO</button>\n      <button class=\"btn sec\" onclick=\"closeChallenge()\">SALIR</button>\n    </div>\n    <div class=\"ch-step\" id=\"ch-game\">\n      <h2 id=\"ch-g-title\" style=\"font-size:11px;margin-bottom:4px;\"></h2>\n      <p id=\"ch-g-desc\" style=\"font-size:11px;color:#aaa;margin-bottom:8px;\"></p>\n      <div id=\"ch-g-content\"></div>\n      <div id=\"ch-g-result\" style=\"min-height:18px;font-size:11px;margin-top:8px;\"></div>\n      <button class=\"btn sec\" id=\"ch-g-close\" onclick=\"closeChallenge()\" style=\"display:none;margin-top:8px;\">CERRAR</button>\n    </div>\n  </div>\n</div>\n\n<!-- SHOP -->\n<div class=\"ov hidden\" id=\"shop-scr\" style=\"z-index:65;\">\n  <div class=\"ob\" style=\"max-width:560px;\">\n    <h2 style=\"font-size:13px;\">&#x1f3ea; TIENDA MERCAQUACK</h2>\n    <p style=\"font-size:11px;color:#f39c12;\">Tienes <span id=\"shop-stars\">0</span> &#x2b50;</p>\n    <div class=\"shop-tabs\">\n      <div class=\"shop-tab active\" onclick=\"switchShopTab('skin')\">Skins</div>\n      <div class=\"shop-tab\" onclick=\"switchShopTab('hat')\">Sombreros</div>\n      <div class=\"shop-tab\" onclick=\"switchShopTab('trail')\">Estelas</div>\n    </div>\n    <div class=\"shop-grid\" id=\"shop-grid\"></div>\n    <button class=\"btn sec\" onclick=\"closeShop()\">VOLVER</button>\n  </div>\n</div>\n\n<!-- WARDROBE -->\n<div class=\"ov hidden\" id=\"wd-scr\" style=\"z-index:65;\">\n  <div class=\"ob\" style=\"max-width:540px;\">\n    <h2 style=\"font-size:13px;\">&#x1f457; GUARDARROPA</h2>\n    <div class=\"wd-layout\">\n      <div class=\"wd-equip\">\n        <div style=\"font-size:8px;color:#f39c12;font-family:'Press Start 2P',monospace;margin-bottom:4px;\">EQUIPADO</div>\n        <div class=\"wd-eslot\" id=\"eq-hat\" onclick=\"unequipSlot('hat')\">\n          <span class=\"eslot-label\">SOMBRERO</span>\n          <span class=\"eslot-icon\" id=\"eq-hat-icon\">&#x2205;</span>\n        </div>\n        <div class=\"wd-eslot\" id=\"eq-skin\" onclick=\"unequipSlot('skin')\">\n          <span class=\"eslot-label\">SKIN</span>\n          <span class=\"eslot-icon\" id=\"eq-skin-icon\">&#x2205;</span>\n        </div>\n        <div class=\"wd-eslot\" id=\"eq-trail\" onclick=\"unequipSlot('trail')\">\n          <span class=\"eslot-label\">ESTELA</span>\n          <span class=\"eslot-icon\" id=\"eq-trail-icon\">&#x2205;</span>\n        </div>\n      </div>\n      <div>\n        <div style=\"font-size:8px;color:#f39c12;font-family:'Press Start 2P',monospace;margin-bottom:6px;\">INVENTARIO</div>\n        <div class=\"wd-grid\" id=\"wd-grid\"></div>\n      </div>\n      <div>\n        <div style=\"font-size:8px;color:#f39c12;font-family:'Press Start 2P',monospace;margin-bottom:6px;\">PREVIEW</div>\n        <canvas id=\"wd-canvas\" width=\"80\" height=\"90\" style=\"border:2px solid rgba(255,200,0,0.3);border-radius:10px;background:rgba(0,80,150,0.3);\"></canvas>\n      </div>\n    </div>\n    <button class=\"btn sec\" onclick=\"closeWardrobe()\">CERRAR</button>\n  </div>\n</div>\n\n<!-- GAME OVER -->\n<div class=\"ov hidden\" id=\"go-scr\" style=\"z-index:90;\">\n  <div class=\"ob\" style=\"border-color:#e74c3c;box-shadow:0 0 70px rgba(231,76,60,.4);\">\n    <div style=\"font-size:56px;animation:goFall .8s ease-out forwards;\">&#x1f986;</div>\n    <h2 style=\"color:#e74c3c;font-size:14px;\">GAME OVER</h2>\n    <p>Los tiburones de tierra vencieron a Mecaquack.</p>\n    <div style=\"background:rgba(255,255,255,0.04);border-radius:8px;padding:10px;margin:10px 0;font-size:11px;line-height:2;\" id=\"go-stats\"></div>\n    <button class=\"btn\" onclick=\"restartGame()\">REINTENTAR</button>\n  </div>\n</div>\n\n<!-- CINEMATIC -->\n<div class=\"ov hidden\" id=\"cin-scr\" style=\"z-index:100;background:#000;\">\n  <div style=\"position:relative;width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:20px;box-sizing:border-box;\">\n    <img id=\"cin-img\" src=\"\" style=\"max-width:88%;max-height:58vh;border-radius:12px;box-shadow:0 0 40px rgba(255,220,100,.3);transition:opacity .7s;object-fit:contain;\" />\n    <div id=\"cin-text\" style=\"max-width:680px;font-size:13px;color:#f0e6d3;text-align:center;margin-top:18px;line-height:1.75;min-height:72px;padding:0 16px;text-shadow:0 2px 8px #000;font-family:'Courier New',monospace;\"></div>\n    <div style=\"margin-top:20px;display:flex;gap:12px;\">\n      <button class=\"btn\" id=\"cin-next-btn\" onclick=\"cinNext()\" style=\"font-size:11px;\">SIGUIENTE &#x27A1;</button>\n      <button class=\"btn sec\" onclick=\"skipCinematic()\" style=\"font-size:10px;padding:5px 14px;\">OMITIR</button>\n    </div>\n    <div id=\"cin-dots\" style=\"position:absolute;bottom:24px;display:flex;gap:8px;\"></div>\n  </div>\n</div>\n\n<!-- BOSS FIGHT -->\n<div class=\"ov hidden\" id=\"boss-scr\" style=\"z-index:95;background:radial-gradient(ellipse at center,#1a0a0a 0%,#0a0005 100%);\">\n  <div class=\"ob\" style=\"max-width:620px;border-color:#c0392b;box-shadow:0 0 80px rgba(192,57,43,.5);max-height:90vh;overflow-y:auto;\">\n    <!-- intro panel -->\n    <div id=\"boss-intro\" style=\"text-align:center;\">\n      <div style=\"font-size:11px;color:#e74c3c;letter-spacing:3px;margin-bottom:8px;\">&#x2620; JEFE FINAL &#x2620;</div>\n      <h2 style=\"color:#f39c12;font-size:14px;margin:4px 0;\">CHIHUAHUA DE AGUA SALADA</h2>\n      <h3 style=\"color:#e67e22;font-size:17px;margin:0 0 10px;\">&ldquo;BOMB&Oacute;N&rdquo;</h3>\n      <img id=\"boss-img-full\" src=\"\" style=\"max-height:200px;border-radius:10px;box-shadow:0 0 30px rgba(231,76,60,.6);margin-bottom:10px;\" />\n      <p style=\"font-size:11px;color:#bbb;max-width:380px;margin:0 auto 14px;\">El guardián del archipiélago te desafía. Demuestra tu dominio de la ingeniería para liberarlo.</p>\n      <button class=\"btn\" onclick=\"startBossFight()\" style=\"background:#c0392b;border-color:#922b21;font-size:12px;\">&#x26A1; COMENZAR BATALLA</button>\n      <br><button class=\"btn sec\" onclick=\"leaveBoss()\" style=\"font-size:9px;\">VOLVER</button>\n    </div>\n    <!-- fight panel -->\n    <div id=\"boss-fight\" style=\"display:none;\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:10px;\">\n        <div style=\"flex:1;\">\n          <div style=\"font-size:9px;color:#4caf50;margin-bottom:3px;\">TÚ &mdash; HP: <span id=\"boss-player-hp\">100</span>/100</div>\n          <div style=\"background:#333;border-radius:4px;height:9px;overflow:hidden;\"><div id=\"boss-phbar\" style=\"background:#4caf50;height:100%;width:100%;transition:width .5s;\"></div></div>\n        </div>\n        <img id=\"boss-img-small\" src=\"\" style=\"width:56px;height:56px;object-fit:cover;border-radius:50%;border:2px solid #c0392b;flex-shrink:0;\" />\n        <div style=\"flex:1;text-align:right;\">\n          <div style=\"font-size:9px;color:#e74c3c;margin-bottom:3px;\">BOMBÓN &mdash; HP: <span id=\"boss-hp\">300</span>/300</div>\n          <div style=\"background:#333;border-radius:4px;height:9px;overflow:hidden;\"><div id=\"boss-hbar\" style=\"background:#e74c3c;height:100%;width:100%;transition:width .5s;\"></div></div>\n        </div>\n      </div>\n      <div id=\"boss-dialogue\" style=\"background:rgba(192,57,43,.15);border:1px solid #922b21;border-radius:8px;padding:9px 12px;font-size:11px;color:#f0c0c0;min-height:38px;margin-bottom:10px;font-style:italic;\"></div>\n      <div id=\"boss-q\" style=\"font-size:12px;color:#fff;margin-bottom:8px;font-weight:bold;line-height:1.5;\"></div>\n      <div id=\"boss-opts\" style=\"display:flex;flex-direction:column;gap:6px;\"></div>\n      <div id=\"boss-result\" style=\"font-size:12px;min-height:22px;margin-top:8px;text-align:center;\"></div>\n      <div style=\"display:flex;justify-content:space-between;margin-top:8px;font-size:10px;color:#888;\">\n        <span>Pregunta <span id=\"boss-qnum\">1</span>/7</span>\n        <span>&#x2B50; <span id=\"boss-stars-live\">0</span></span>\n      </div>\n    </div>\n    <!-- dead panel -->\n    <div id=\"boss-dead\" style=\"display:none;text-align:center;\">\n      <div id=\"boss-death-anim\" style=\"font-size:60px;animation:goFall .8s ease-out forwards;\">&#x1F436;</div>\n      <h2 style=\"color:#4caf50;font-size:14px;margin:8px 0;\">¡GAME OVER PARA BOMB&Oacute;N!</h2>\n      <p style=\"font-size:11px;color:#aaa;max-width:380px;margin:0 auto 14px;\">¡Has demostrado tu dominio de la ingeniería! El archipiélago está a salvo y la familia de Mecaquack es libre.</p>\n      <button class=\"btn\" onclick=\"showCredits()\" style=\"background:#27ae60;border-color:#1e8449;\">&#x1F3C6; VER CR&Eacute;DITOS</button>\n    </div>\n  </div>\n</div>\n\n<!-- CREDITS -->\n<div class=\"ov hidden\" id=\"credits-scr\" style=\"z-index:97;background:linear-gradient(180deg,#000 0%,#080814 60%,#000 100%);\">\n  <div style=\"position:relative;width:100%;height:100%;overflow:hidden;\">\n    <canvas id=\"credits-stars-canvas\" style=\"position:absolute;inset:0;pointer-events:none;\"></canvas>\n    <div id=\"credits-roll\" style=\"position:absolute;width:100%;text-align:center;top:100%;padding:0 24px 220px;box-sizing:border-box;\">\n      <div style=\"font-size:32px;color:#f39c12;font-family:'Courier New',monospace;margin-bottom:6px;letter-spacing:4px;\">&#x2B50; MECAQUACK &#x2B50;</div>\n      <div style=\"font-size:12px;color:#777;margin-bottom:70px;font-family:'Courier New',monospace;letter-spacing:2px;\">UNA AVENTURA DE INGENIERÍA</div>\n\n      <div style=\"font-size:18px;color:#4fc3f7;margin-bottom:8px;font-family:'Courier New',monospace;letter-spacing:3px;\">EQUIPO MARAVILLA</div>\n      <div style=\"width:220px;border-top:1px solid #4fc3f7;margin:0 auto 36px;\"></div>\n\n      <div style=\"margin-bottom:24px;\"><div style=\"font-size:10px;color:#888;margin-bottom:4px;letter-spacing:1px;\">DIRECTOR DEL PROYECTO</div><div style=\"font-size:14px;color:#fff;\">Equipo Maravilla</div></div>\n      <div style=\"margin-bottom:24px;\"><div style=\"font-size:10px;color:#888;margin-bottom:4px;letter-spacing:1px;\">PROGRAMACIÓN Y DESARROLLO</div><div style=\"font-size:14px;color:#fff;\">Equipo Maravilla</div></div>\n      <div style=\"margin-bottom:24px;\"><div style=\"font-size:10px;color:#888;margin-bottom:4px;letter-spacing:1px;\">ARTE Y DISEÑO VISUAL</div><div style=\"font-size:14px;color:#fff;\">Equipo Maravilla</div></div>\n      <div style=\"margin-bottom:24px;\"><div style=\"font-size:10px;color:#888;margin-bottom:4px;letter-spacing:1px;\">DISEÑO DE NIVELES Y RETOS</div><div style=\"font-size:14px;color:#fff;\">Equipo Maravilla</div></div>\n      <div style=\"margin-bottom:24px;\"><div style=\"font-size:10px;color:#888;margin-bottom:4px;letter-spacing:1px;\">GUIÓN Y NARRATIVA</div><div style=\"font-size:14px;color:#fff;\">Equipo Maravilla</div></div>\n      <div style=\"margin-bottom:24px;\"><div style=\"font-size:10px;color:#888;margin-bottom:4px;letter-spacing:1px;\">CONTROL DE CALIDAD Y TESTING</div><div style=\"font-size:14px;color:#fff;\">Equipo Maravilla</div></div>\n      <div style=\"margin-bottom:24px;\"><div style=\"font-size:10px;color:#888;margin-bottom:4px;letter-spacing:1px;\">PRESENTACIÓN Y COMUNICACIÓN</div><div style=\"font-size:14px;color:#fff;\">Equipo Maravilla</div></div>\n\n      <div style=\"width:300px;border-top:1px solid #444;margin:50px auto;\"></div>\n\n      <div style=\"font-size:17px;color:#f39c12;margin-bottom:12px;letter-spacing:2px;\">AGRADECIMIENTOS ESPECIALES</div>\n      <div style=\"font-size:15px;color:#e8c87a;margin-bottom:6px;font-weight:bold;\">Instituto Tecnológico Superior de Irapuato</div>\n      <div style=\"font-size:11px;color:#999;margin-bottom:70px;\">Por su confianza, apoyo y el espacio para crear este proyecto</div>\n\n      <div style=\"width:300px;border-top:1px solid #444;margin:0 auto 50px;\"></div>\n\n      <div style=\"font-size:24px;margin-bottom:10px;\">&#x1F986;</div>\n      <div style=\"font-size:14px;color:#4caf50;margin-bottom:6px;\">Mecaquack reunió a su familia.</div>\n      <div style=\"font-size:11px;color:#888;margin-bottom:8px;\">El archipiélago volvió a la paz.</div>\n      <div style=\"font-size:10px;color:#555;margin-bottom:100px;\">Gracias por jugar &mdash; 2024</div>\n      <div style=\"font-size:11px;color:#6fb1ff;margin-bottom:100px;\">Publicado en DivierteTEC &middot; InnovaTec Hackatec 2026</div>\n    </div>\n    <div style=\"position:absolute;top:18px;right:20px;\">\n      <button class=\"btn sec\" onclick=\"creditsEnd()\" style=\"font-size:10px;padding:5px 14px;\">TERMINAR</button>\n    </div>\n  </div>\n</div>\n\n<div id=\"notif\"></div>\n<div class=\"ov hidden\" id=\"pause-scr\" style=\"z-index:85;\"><div class=\"ob\"><h2>PAUSA</h2><p>Tu partida se guarda automáticamente.</p>\n  <button class=\"btn\" onclick=\"togglePause()\">CONTINUAR</button></div></div>\n<div id=\"touch-ui\"><div id=\"joy\"><div id=\"joy-knob\"></div></div>\n  <div id=\"tbtns\"><button data-tk=\"sword\">⚔️</button><button data-tk=\"use\">E</button><button data-tk=\"drone\">🚁</button><button data-tk=\"wd\">👗</button><button data-tk=\"pause\">⏸</button></div></div>\n<!-- Solo para jugar fuera de DivierteTEC; dentro de la plataforma se inyecta el SDK real -->\n\n<script>\n\n/* ── DIVIERTETEC: SDK de logros (inyectado por la plataforma; ver divierte-tec-sdk.js) ── */\nconst SDK=window.DivierteTEC||{unlock(){},progress(){},setStat(){}};\nconst SAVE_KEY='mecaquack_save_v1';\nconst LAIR={tx:107,ty:79,need:10,get x(){return this.tx*TILE;},get y(){return this.ty*TILE;}};\nlet bossPractice=false,bossFromWorld=false,_saveT=0;\n\nconst canvas=document.getElementById('gc'),ctx=canvas.getContext('2d');\nlet W,H;\nfunction resize(){W=canvas.width=window.innerWidth;H=canvas.height=window.innerHeight;}\nresize();window.addEventListener('resize',resize);\n\n/* ── IMAGES ── */\nconst duckImg=new Image(),sharkImg=new Image(),treeImg=new Image(),houseImg=new Image(),\n  bushImg=new Image(),rockImg=new Image(),grassImg=new Image(),coalImg=new Image(),\n  whaleImg=new Image(),willowImg=new Image();\nconst cin1Img=new Image(),cin2Img=new Image(),cin3Img=new Image(),cin4Img=new Image(),bossFullImg=new Image(),bossSmallImg=new Image();\nduckImg.src='img/pato.png';\nsharkImg.src='img/tiburon.png';\ntreeImg.src='img/arbol.png';\nhouseImg.src='img/casa.png';\nbushImg.src='img/arbusto.png';\nrockImg.src='img/roca.png';\ngrassImg.src='img/pasto.png';\ncoalImg.src='img/carbon.png';\nwhaleImg.src='img/ballena.png';\nwillowImg.src='img/sauce.png';\ncin1Img.src='img/cinematica1.png';\ncin2Img.src='img/cinematica2.png';\ncin3Img.src='img/cinematica3.png';\ncin4Img.src='img/cinematica4.png';\nbossFullImg.src='img/bombon.png';\nbossSmallImg.src='img/bombon-mini.png';\n\n/* ── WORLD ── */\nconst TILE=40,WORLD_W=130,WORLD_H=100;\nconst world=Array.from({length:WORLD_H},()=>new Array(WORLD_W).fill(0));\nconst TD={\n  0:{c:'#0d4a8a',b:'#0a3a6a',solid:true},\n  1:{c:'#3a7d44',b:'#2e6636',solid:false},\n  2:{c:'#c8a84b',b:'#b0943a',solid:false},\n  3:{c:'#8b2010',b:'#6a1010',solid:false},\n  4:{c:'#6b6b6b',b:'#555',solid:false},\n  5:{c:'#2d5a27',b:'#1e3e1a',solid:false},\n  6:{c:'#b8d4f0',b:'#9ab8d8',solid:false},\n  7:{c:'#c8a84b',b:'#a08030',solid:false},\n  8:{c:'#e74c3c',b:'#c0392b',solid:true},\n  9:{c:'#95a5a6',b:'#7f8c8d',solid:true},\n  10:{c:'#e8c97a',b:'#c8a858',solid:false},\n  11:{c:'#d8eeff',b:'#aaccee',solid:false},\n  12:{c:'#7a6855',b:'#5a5040',solid:false},\n  13:{c:'#5db8a0',b:'#3d9880',solid:false},\n};\n\nfunction ST(x,y,v){if(x>=0&&x<WORLD_W&&y>=0&&y<WORLD_H)world[y][x]=v;}\nfunction fillR(x,y,w,h,v){for(let j=y;j<y+h;j++)for(let i=x;i<x+w;i++)ST(i,j,v);}\nfunction fillC(cx,cy,r,v){for(let j=cy-r;j<=cy+r;j++)for(let i=cx-r;i<=cx+r;i++)if(Math.hypot(i-cx,j-cy)<=r)ST(i,j,v);}\nfunction fillPoly(pts,v){\n  let minY=pts[0][1],maxY=pts[0][1];\n  pts.forEach(p=>{if(p[1]<minY)minY=p[1];if(p[1]>maxY)maxY=p[1];});\n  for(let y=Math.floor(minY);y<=Math.ceil(maxY);y++){\n    const xs=[];\n    for(let i=0;i<pts.length;i++){\n      const a=pts[i],b=pts[(i+1)%pts.length];\n      if((a[1]<=y&&b[1]>y)||(b[1]<=y&&a[1]>y))\n        xs.push(a[0]+(y-a[1])/(b[1]-a[1])*(b[0]-a[0]));\n    }\n    xs.sort((a,b)=>a-b);\n    for(let k=0;k<xs.length-1;k+=2)\n      for(let x=Math.floor(xs[k]);x<=Math.ceil(xs[k+1]);x++)ST(x,y,v);\n  }\n}\n\n/* ── ORIGINAL ISLANDS (same positions as before) ── */\nfillPoly([[28,19],[50,18],[55,23],[53,37],[44,43],[31,41],[25,35],[23,27]],1);\nfillR(35,27,12,4,7);fillR(38,25,6,11,7);\nfillPoly([[5,4],[19,3],[23,9],[21,19],[14,23],[7,21],[3,15],[4,8]],3);\nfillC(13,12,4,8);\nfillPoly([[55,3],[73,2],[77,7],[75,17],[68,21],[57,19],[53,13],[54,6]],4);\nfillC(65,10,3,9);\nfillPoly([[4,39],[17,37],[23,41],[23,53],[16,57],[5,55],[1,51],[2,44]],5);\nfillPoly([[56,41],[69,39],[75,43],[77,53],[73,58],[62,59],[54,55],[52,49],[55,43]],6);\n\n/* ── NEW ISLANDS ── */\n// Desert island (type 10) - top right\nfillPoly([[87,7],[104,6],[109,11],[107,22],[99,26],[88,24],[83,18],[84,10]],10);\nfillC(96,15,3,10);\n// Arctic island (type 11) - right middle\nfillPoly([[92,33],[109,32],[113,37],[111,48],[103,52],[92,50],[88,44],[89,36]],11);\nfillC(100,41,3,11);\n// Coral island (type 13) - bottom left\nfillPoly([[5,64],[19,62],[24,66],[24,78],[17,82],[6,80],[2,75],[3,67]],13);\nfillC(14,71,3,13);\n// Market/Ruins island (type 12) - bottom center, has shop\nfillPoly([[52,64],[68,62],[73,67],[72,79],[64,83],[53,81],[49,76],[50,67]],12);\nfillC(61,72,3,12);\n// Extra decorative island (type 1) - far bottom right\nfillPoly([[100,72],[114,70],[118,75],[116,85],[109,88],[99,86],[95,81],[96,74]],1);\nfillC(107,79,3,1);\n\n/* ── ISLAND DEFS ── */\nconst ISLANDS=[\n  {id:'central',name:'Archiparalelo',cx:40*TILE,cy:30*TILE},\n  {id:'volcano',name:'Metalandia',cx:13*TILE,cy:13*TILE},\n  {id:'mountain',name:'Terralita',cx:65*TILE,cy:11*TILE},\n  {id:'swamp',name:'Pantanórbita',cx:13*TILE,cy:47*TILE},\n  {id:'clouds',name:'Ventilandia',cx:65*TILE,cy:49*TILE},\n  {id:'desert',name:'Arenópolis',cx:96*TILE,cy:15*TILE},\n  {id:'arctic',name:'Criolandia',cx:100*TILE,cy:41*TILE},\n  {id:'coral',name:'Coralinda',cx:14*TILE,cy:71*TILE},\n  {id:'market',name:'Mercaquack',cx:61*TILE,cy:72*TILE},\n  {id:'jungle',name:'Selvarrón',cx:107*TILE,cy:79*TILE},\n];\n\n/* ── TECH ── */\nconst TECH_DEF={\n  central:{key:'KeyQ',name:'Archiparalelo',icon:'🛡️',\n    act(){GS.shieldActive=true;showNotif('Escudo activado');setTimeout(()=>GS.shieldActive=false,8000);}},\n  volcano:{key:'KeyF',name:'Metalandia',icon:'🔥',\n    act(){const P=GS.player;GS.sharks.forEach(s=>{if(!s.dead&&Math.hypot(s.x-P.x,s.y-P.y)<180){killShark(s);}});showNotif('Flama activada');}},\n  mountain:{key:'KeyG',name:'Terralita',icon:'🪨',\n    act(){GS.player.hp=Math.min(150,GS.player.hp+50);updateHUD();showNotif('Armadura +50 vida');}},\n  swamp:{key:'KeyH',name:'Pantanórbita',icon:'🪤',\n    act(){GS.traps.push({x:GS.player.x,y:GS.player.y,life:12});showNotif('Trampa colocada');}},\n  clouds:{key:'KeyT',name:'Ventilandia',icon:'🌀',\n    act(){const P=GS.player;GS.sharks.forEach(s=>{if(!s.dead){const dx=s.x-P.x,dy=s.y-P.y,d=Math.hypot(dx,dy)||1;s.x+=dx/d*200;s.y+=dy/d*200;}});showNotif('Turbina activada');}},\n};\n\n\n/* ── CHALLENGE DEFINITIONS ── */\n/* each challenge has: theory, and either a single type/q/opts/ans/items/correct/pairs\n   OR a variants[] array with per-difficulty content.\n   difficulty 1=easy(no timer), 2=normal(45s), 3=hard(25s, no theory) */\nconst CH_DEFS=[\n  /* ── CENTRAL ── */\n  {id:'c0',tx:38,ty:27,icon:'📐',title:'Vectores',\n   theory:{h:'Vectores y Componentes',body:'<p>Al descomponer velocidad <span class=\"fml\">v</span> a angulo <span class=\"fml\">θ</span>:</p><ul><li>Horizontal: <span class=\"fml\">vx = v·cos(θ)</span></li><li>Vertical: <span class=\"fml\">vy = v·sin(θ)</span></li></ul><p>Angulo de maximo alcance: <strong>45 grados</strong>.</p>'},\n   type:'quiz',q:'Componente vertical de v=20 m/s a 30°:',opts:['10 m/s','17.3 m/s','20 m/s','14.1 m/s'],ans:0,reward:'🔩',stars:2},\n\n  {id:'c1',tx:44,ty:32,icon:'⚖️',title:'Leyes de Newton',\n   theory:{h:'Las 3 Leyes de Newton',body:'<p><strong>1a:</strong> Inercia — reposo sin fuerza.</p><p><strong>2a:</strong> <span class=\"fml\">F = m·a</span></p><p><strong>3a:</strong> Accion = -Reaccion.</p>'},\n   type:'sequence',prompt:'Ordena las leyes de Newton del 1 al 3:',\n   items:['F = m·a  (2a Ley)','Inercia — reposo sin fuerza  (1a Ley)','Accion = -Reaccion  (3a Ley)'],\n   correct:[1,0,2],reward:'🔋',stars:2},\n\n  {id:'c2',tx:39,ty:35,icon:'🗺️',title:'Cinematica',\n   theory:{h:'Movimiento con Aceleracion',body:'<p>Ecuaciones:<ul><li><span class=\"fml\">v = v₀ + a·t</span></li><li><span class=\"fml\">x = v₀·t + ½·a·t²</span></li></ul>Caida libre: <span class=\"fml\">g = 9.8 m/s²</span></p>'},\n   type:'match',pairs:[['Velocidad inicial nula','v₀ = 0'],['Caida libre','g = 9.8 m/s²'],['Posicion con aceleracion','x = ½·a·t²'],['Sin aceleracion','v = constante']],\n   reward:'📡',stars:2},\n\n  {id:'c3',tx:43,ty:28,icon:'🏗️',title:'Equilibrio',\n   theory:{h:'Equilibrio de Fuerzas',body:'<p>Equilibrio estatico: <span class=\"fml\">ΣF = 0</span></p>'},\n   type:'quiz',q:'La suma de fuerzas en equilibrio es:',opts:['ΣF = ma','ΣF = 0','ΣF = mv','ΣF = W'],ans:1,reward:'🔧',stars:2},\n\n  /* ── VOLCANO ── */\n  {id:'v0',tx:12,ty:10,icon:'⚗️',title:'Reduccion de Metales',\n   theory:{h:'Alto Horno',body:'<p><span class=\"fml\">Fe₂O₃ + 3CO → 2Fe + 3CO₂</span></p><p>CO reduce el oxido a mas de 1200°C.</p>'},\n   type:'quiz',q:'Productos: Fe₂O₃ + 3CO →',opts:['2Fe + 3CO₂','FeO + CO','Fe + CO₂','Fe₂ + CO'],ans:0,reward:'🔩',stars:2},\n\n  {id:'v1',tx:16,ty:14,icon:'🔥',title:'Puntos de Fusion',\n   theory:{h:'Fusion de Metales',body:'<ul><li>Plomo: <span class=\"fml\">327°C</span></li><li>Aluminio: <span class=\"fml\">660°C</span></li><li>Hierro: <span class=\"fml\">1538°C</span></li><li>Tungsteno: <span class=\"fml\">3422°C</span></li></ul>'},\n   type:'sequence',prompt:'Ordena de MENOR a MAYOR punto de fusion:',\n   items:['Hierro  1538°C','Plomo  327°C','Tungsteno  3422°C','Aluminio  660°C'],\n   correct:[1,3,0,2],reward:'🔧',stars:2},\n\n  {id:'v2',tx:10,ty:14,icon:'💧',title:'Aleaciones',\n   theory:{h:'Aleaciones Metalicas',body:'<ul><li>Acero: Hierro + Carbono</li><li>Bronce: Cobre + Estaño</li><li>Laton: Cobre + Zinc</li><li>Duraluminio: Aluminio + Cobre</li></ul>'},\n   type:'match',pairs:[['Cobre + Estaño','Bronce'],['Hierro + Carbono','Acero'],['Cobre + Zinc','Laton'],['Aluminio + Cobre','Duraluminio']],\n   reward:'🔋',stars:2},\n\n  /* ── MOUNTAIN ── */\n  {id:'m0',tx:63,ty:8,icon:'💎',title:'Modulo de Young',\n   theory:{h:'Elasticidad',body:'<p><span class=\"fml\">E = σ / ε</span></p><ul><li>Madera: ~10 GPa</li><li>Aluminio: ~70 GPa</li><li>Acero: ~200 GPa</li></ul>'},\n   type:'quiz',q:'Material con mayor Modulo de Young:',opts:['Madera','Plastico','Acero','Aluminio'],ans:2,reward:'🔧',stars:2},\n\n  {id:'m1',tx:67,ty:12,icon:'🔩',title:'Esfuerzo y Deformacion',\n   theory:{h:'Curva Esfuerzo-Deformacion',body:'<ul><li>Zona elastica: recupera forma</li><li>Limite elastico: max sin deformacion</li><li>Zona plastica: deformacion permanente</li></ul>'},\n   type:'match',pairs:[['Recupera forma','Zona elastica'],['Sin zona plastica','Material fragil'],['Deformacion permanente','Zona plastica'],['σ = E·ε','Ley de Hooke']],\n   reward:'📡',stars:2},\n\n  /* ── SWAMP ── */\n  {id:'s0',tx:11,ty:45,icon:'🔧',title:'Palancas',\n   theory:{h:'Tipos de Palancas',body:'<ul><li>1er genero: fulcro centro (tijeras)</li><li>2do genero: carga centro (carretilla)</li><li>3er genero: fuerza centro (pinzas)</li></ul><p>VM = <span class=\"fml\">Fres / Fesfuerzo</span></p>'},\n   type:'sequence',prompt:'Ordena: 1er, 2do, 3er genero:',\n   items:['Fuerza al centro — pinzas  (3er)','Fulcro al centro — tijeras  (1er)','Carga al centro — carretilla  (2do)'],\n   correct:[1,2,0],reward:'🔩',stars:2},\n\n  {id:'s1',tx:16,ty:50,icon:'⚙️',title:'Engranajes',\n   theory:{h:'Relacion de Transmision',body:'<p><span class=\"fml\">i = N_conductor / N_conducido</span></p><p>20 dientes / 60 dientes = <span class=\"fml\">1:3</span></p>'},\n   type:'quiz',q:'Conductor 20T, conducido 60T. Relacion:',opts:['3:1','1:3','1:2','2:1'],ans:1,reward:'🔧',stars:2},\n\n  /* ── CLOUDS ── */\n  {id:'cl0',tx:63,ty:47,icon:'🌬️',title:'Bernoulli',\n   theory:{h:'Principio de Bernoulli',body:'<p><span class=\"fml\">P + ½ρv² + ρgh = cte</span></p><p>Mayor velocidad → menor presion. Genera sustentacion.</p>'},\n   type:'quiz',q:'Al aumentar velocidad del fluido:',opts:['Presion sube','Presion baja','No cambia','Temperatura baja'],ans:1,reward:'🔋',stars:2},\n\n  {id:'cl1',tx:68,ty:52,icon:'✈️',title:'Aerodinamica',\n   theory:{h:'Fuerzas en el Vuelo',body:'<ul><li>Sustentacion: perpendicular — arriba</li><li>Peso: gravedad — abajo</li><li>Empuje: motores — adelante</li><li>Arrastre: resistencia — atras</li></ul><p>Vuelo nivel: <span class=\"fml\">L=W, T=D</span></p>'},\n   type:'match',pairs:[['Perpendicular al flujo','Sustentacion'],['Resistencia al avance','Arrastre'],['Motor hacia adelante','Empuje'],['Gravedad','Peso']],\n   reward:'📡',stars:2},\n\n  /* ── DESERT ── */\n  {id:'d0',tx:92,ty:11,icon:'🌡️',title:'Transferencia de Calor',\n   theory:{h:'Modos de Transferencia',body:'<ul><li><strong>Conduccion:</strong> solidos, contacto directo</li><li><strong>Conveccion:</strong> fluidos en movimiento</li><li><strong>Radiacion:</strong> ondas EM, no necesita materia</li></ul>'},\n   variants:[\n     {diff:1,type:'quiz',q:'Modo que NO necesita materia:',opts:['Conduccion','Conveccion','Radiacion','Fusion'],ans:2,stars:2},\n     {diff:2,type:'quiz',q:'En un solido metalico, el modo predominante es:',opts:['Conveccion','Radiacion','Conduccion','Evaporacion'],ans:2,stars:3},\n     {diff:3,type:'match',pairs:[['No necesita materia','Radiacion'],['Fluidos en mov.','Conveccion'],['Contacto solidos','Conduccion'],['Q = m·c·ΔT','Calor sensible']],stars:4},\n   ],reward:'🌡️'},\n\n  {id:'d1',tx:99,ty:18,icon:'⚡',title:'1ra Ley Termodinamica',\n   theory:{h:'Conservacion de Energia',body:'<p><span class=\"fml\">ΔU = Q - W</span></p><p>ΔU = variacion energia interna, Q = calor, W = trabajo realizado.</p>'},\n   variants:[\n     {diff:1,type:'quiz',q:'ΔU = Q - W. ΔU representa:',opts:['Calor','Trabajo','Energia interna','Temperatura'],ans:2,stars:2},\n     {diff:2,type:'quiz',q:'Proceso adiabático: Q=0, W>0. Entonces ΔU:',opts:['Aumenta','Permanece igual','Disminuye','Es infinita'],ans:2,stars:3},\n     {diff:3,type:'sequence',prompt:'Ordena etapas del ciclo Carnot:',items:['Compresion adiab.','Expansion isotermica','Compresion isotermica','Expansion adiab.'],correct:[1,3,2,0],stars:4},\n   ],reward:'⚡'},\n\n  /* ── ARCTIC ── */\n  {id:'i0',tx:96,ty:37,icon:'❄️',title:'Dilatacion Termica',\n   theory:{h:'Expansion Termica',body:'<p>Al calentar, los materiales se expanden:</p><p><span class=\"fml\">ΔL = α·L₀·ΔT</span></p><p>α = coef. dilatacion, mayor en gases.</p>'},\n   variants:[\n     {diff:1,type:'quiz',q:'Un metal al calentarse:',opts:['Se contrae','Se dilata','No cambia','Se derrite siempre'],ans:1,stars:2},\n     {diff:2,type:'quiz',q:'Mayor coeficiente de dilatacion lineal:',opts:['Acero','Vidrio','Aluminio','Hierro'],ans:2,stars:3},\n     {diff:3,type:'match',pairs:[['Se expande mas','Gas',''],['Se expande menos','Solido'],['α·L₀·ΔT','Dilatacion lineal'],['Puentes con juntas','Compensan dilatacion']].map(p=>p.slice(0,2)),stars:4},\n   ],reward:'❄️'},\n\n  {id:'i1',tx:103,ty:44,icon:'🌡',title:'Cambios de Fase',\n   theory:{h:'Estados de la Materia',body:'<ul><li>Fusion: solido→liquido</li><li>Vaporizacion: liquido→gas</li><li>Solidificacion: liquido→solido</li><li>Condensacion: gas→liquido</li><li>Sublimacion: solido→gas</li></ul>'},\n   variants:[\n     {diff:1,type:'quiz',q:'Agua liquida que se convierte en vapor:',opts:['Fusion','Solidificacion','Vaporizacion','Sublimacion'],ans:2,stars:2},\n     {diff:2,type:'sequence',prompt:'Ordena de menor a mayor energia:',items:['Gas','Liquido','Solido'],correct:[2,1,0],stars:3},\n     {diff:3,type:'match',pairs:[['Solido → Liquido','Fusion'],['Liquido → Gas','Vaporizacion'],['Gas → Liquido','Condensacion'],['Solido → Gas','Sublimacion']],stars:4},\n   ],reward:'🌡'},\n\n  /* ── CORAL ── */\n  {id:'co0',tx:10,ty:67,icon:'🌊',title:'Principio de Arquimedes',\n   theory:{h:'Empuje en Fluidos',body:'<p>Todo cuerpo sumergido recibe un empuje igual al peso del fluido desplazado:</p><p><span class=\"fml\">E = ρ·g·V</span></p>'},\n   variants:[\n     {diff:1,type:'quiz',q:'Un cuerpo flota cuando su densidad es:',opts:['Mayor que el fluido','Igual al fluido','Menor que el fluido','Cero'],ans:2,stars:2},\n     {diff:2,type:'quiz',q:'Empuje = peso del fluido desplazado. Formula:',opts:['E = m·g','E = ρ·g·V','E = P/A','E = ½·ρ·v²'],ans:1,stars:3},\n     {diff:3,type:'match',pairs:[['Flota','ρ_obj < ρ_fluido'],['Se hunde','ρ_obj > ρ_fluido'],['Empuje','ρ·g·V'],['Inventor','Arquimedes']],stars:4},\n   ],reward:'🌊'},\n\n  {id:'co1',tx:17,ty:75,icon:'💧',title:'Principio de Pascal',\n   theory:{h:'Presion en Fluidos',body:'<p>La presion aplicada a un fluido se transmite por igual en todas direcciones:</p><p><span class=\"fml\">P = F / A</span></p>'},\n   variants:[\n     {diff:1,type:'quiz',q:'La presion se transmite en fluidos:',opts:['Solo hacia abajo','Solo hacia arriba','En todas direcciones','Solo horizontalmente'],ans:2,stars:2},\n     {diff:2,type:'quiz',q:'Si duplicas el area, la presion con la misma fuerza:',opts:['Se duplica','Se mantiene','Se reduce a la mitad','Se cuadruplica'],ans:2,stars:3},\n     {diff:3,type:'sequence',prompt:'Ordena por presion (mayor a menor) en agua:',items:['Superficie (0m)','30m profundidad','10m profundidad'],correct:[1,2,0],stars:4},\n   ],reward:'💧'},\n];\n\n\n/* ── SHOP ITEMS ── */\nconst SHOP_ITEMS=[\n  {id:'skin_gold',name:'Pato Dorado',icon:'🟡',cat:'skin',cost:15,desc:'Reluciente'},\n  {id:'skin_blue',name:'Pato Marino',icon:'🔵',cat:'skin',cost:15,desc:'Fresco'},\n  {id:'skin_pink',name:'Pato Rosa',icon:'🩷',cat:'skin',cost:15,desc:'Adorable'},\n  {id:'skin_dark',name:'Pato Nocturno',icon:'⬛',cat:'skin',cost:20,desc:'Misterioso'},\n  {id:'skin_green',name:'Pato Jungla',icon:'🟢',cat:'skin',cost:15,desc:'Selvático'},\n  {id:'hat_pirate',name:'Sombrero Pirata',icon:'🏴‍☠️',cat:'hat',cost:10,desc:'Arr!'},\n  {id:'hat_crown',name:'Corona Real',icon:'👑',cat:'hat',cost:25,desc:'Realeza'},\n  {id:'hat_cowboy',name:'Sombrero Vaquero',icon:'🤠',cat:'hat',cost:10,desc:'Yee-haw!'},\n  {id:'hat_party',name:'Gorro Fiesta',icon:'🎊',cat:'hat',cost:8,desc:'Celebracion!'},\n  {id:'hat_tophat',name:'Chistera',icon:'🎩',cat:'hat',cost:15,desc:'Elegante'},\n  {id:'trail_fire',name:'Estela Fuego',icon:'🔥',cat:'trail',cost:20,desc:'Deja llamas'},\n  {id:'trail_ice',name:'Estela Hielo',icon:'❄️',cat:'trail',cost:20,desc:'Deja cristales'},\n  {id:'trail_star',name:'Estela Estelar',icon:'⭐',cat:'trail',cost:20,desc:'Deja estrellas'},\n];\nconst SKIN_TINTS={\n  skin_gold:'rgba(255,210,0,0.48)',skin_blue:'rgba(30,144,255,0.42)',\n  skin_pink:'rgba(255,105,180,0.42)',skin_dark:'rgba(15,15,50,0.62)',\n  skin_green:'rgba(30,180,60,0.42)',\n};\nconst DRONE_PARTS=[\n  {id:'heli',emoji:'🔩',name:'Helice',slot:'motor'},\n  {id:'bat',emoji:'🔋',name:'Bateria',slot:'power'},\n  {id:'chassis',emoji:'🔧',name:'Chasis',slot:'frame'},\n  {id:'sensor',emoji:'📡',name:'Sensor',slot:'nav'},\n];\nconst DRONE_SLOTS=['frame','power','motor','nav'];\nconst SLOT_NAMES={frame:'🔧 Chasis',power:'🔋 Bateria',motor:'🔩 Helice',nav:'📡 Sensor'};\nlet droneAssembled={};\n\n/* ── GAME STATE ── */\nconst GS={\n  running:false,paused:false,\n  player:{x:0,y:0,hp:100,dir:0,swordTimer:0,invTimer:0,hasDrone:false},\n  camera:{x:0,y:0},keys:{},kills:0,stars:0,\n  doneChallenges:new Set(),inventory:[],\n  sharks:[],whales:[],challenges:[],particles:[],traps:[],\n  techs:{central:false,volcano:false,mountain:false,swamp:false,clouds:false},\n  shieldActive:false,\n  cosmetics:{owned:new Set(),hat:null,skin:null,trail:null},\n  visited:new Set(),starsEarned:0,hardCount:0,bossDefeated:false,\n};\n\n/* ── GUARDADO DE PARTIDA ── */\nfunction saveGame(){\n  if(!GS.running&&!GS.bossDefeated) return;\n  try{localStorage.setItem(SAVE_KEY,JSON.stringify({\n    stars:GS.stars,kills:GS.kills,done:[...GS.doneChallenges],inventory:GS.inventory,hasDrone:GS.player.hasDrone,\n    hp:GS.player.hp,x:GS.player.x,y:GS.player.y,techs:GS.techs,visited:[...GS.visited],starsEarned:GS.starsEarned,\n    hardCount:GS.hardCount,bossDefeated:GS.bossDefeated,\n    cosmetics:{owned:[...GS.cosmetics.owned],hat:GS.cosmetics.hat,skin:GS.cosmetics.skin,trail:GS.cosmetics.trail}\n  }));}catch(e){}\n}\nfunction loadSave(){try{return JSON.parse(localStorage.getItem(SAVE_KEY));}catch(e){return null;}}\nfunction continueGame(){\n  const d=loadSave();if(!d) return startCinematic();\n  GS.stars=d.stars||0;GS.kills=d.kills||0;GS.doneChallenges=new Set(d.done||[]);GS.inventory=d.inventory||[];\n  GS.player.hasDrone=!!d.hasDrone;GS.player.hp=d.hp>0?d.hp:100;GS.techs=Object.assign(GS.techs,d.techs||{});\n  GS.visited=new Set(d.visited||[]);GS.starsEarned=d.starsEarned||GS.stars;GS.hardCount=d.hardCount||0;GS.bossDefeated=!!d.bossDefeated;\n  const c=d.cosmetics||{};GS.cosmetics.owned=new Set(c.owned||[]);GS.cosmetics.hat=c.hat||null;GS.cosmetics.skin=c.skin||null;GS.cosmetics.trail=c.trail||null;\n  if(GS.player.hasDrone) DRONE_SLOTS.forEach(sl=>{droneAssembled[sl]=DRONE_PARTS.find(p=>p.slot===sl).emoji;});\n  Object.keys(GS.techs).forEach(id=>{if(GS.techs[id]) document.getElementById('ts-'+id)?.classList.add('unlocked');});\n  document.getElementById('kv').textContent=GS.kills;\n  startGame();\n  if(d.x&&d.y){GS.player.x=d.x;GS.player.y=d.y;}\n  showNotif('Partida cargada — ¡bienvenido de vuelta!');\n}\nfunction addStars(n){GS.stars+=n;GS.starsEarned+=n;SDK.progress('meca_estrellas',GS.starsEarned);}\n\n/* ── SPAWN SHARKS ── */\nconst SHARK_SPAWNS=[\n  {x:37,y:33},{x:42,y:28},{x:41,y:35},\n  {x:12,y:10},{x:15,y:15},\n  {x:63,y:8},{x:67,y:13},\n  {x:11,y:44},{x:15,y:51},\n  {x:63,y:48},{x:68,y:53},\n  // Desert\n  {x:92,y:11},{x:100,y:18},\n  // Arctic\n  {x:97,y:37},{x:104,y:44},\n  // Coral\n  {x:10,y:67},{x:17,y:73},\n];\n\nfunction spawnSharks(){\n  GS.sharks=SHARK_SPAWNS.map((p,i)=>({\n    id:i,x:p.x*TILE,y:p.y*TILE,\n    spawnX:p.x*TILE,spawnY:p.y*TILE,\n    hp:3,maxHp:3,vx:0,vy:0,\n    hitTimer:0,dead:false,\n    respawnTimer:0,\n    angle:Math.random()*Math.PI*2,\n    floatOff:Math.random()*Math.PI*2,\n    speed:0.8+Math.random()*0.5,\n    state:'patrol',slowTimer:0,\n    patrolTimer:Math.random()*2,wallCooldown:0,\n  }));\n}\n\n/* ── SPAWN WHALES ── */\nconst WHALE_POS=[\n  {x:30,y:3},{x:65,y:5},{x:3,y:22},{x:3,y:55},\n  {x:42,y:62},{x:78,y:30},{x:112,y:20},{x:120,y:57},{x:80,y:88},\n];\nfunction spawnWhales(){\n  GS.whales=WHALE_POS.map((p,i)=>({\n    x:p.x*TILE,y:p.y*TILE,\n    angle:Math.random()*Math.PI*2,\n    floatOff:Math.random()*Math.PI*2,\n    speed:0.3+Math.random()*0.2,\n    dir:Math.random()<0.5?1:-1,\n  }));\n}\n\nfunction initChallenges(){\n  GS.challenges=CH_DEFS.map(d=>({...d,wx:d.tx*TILE+TILE/2,wy:d.ty*TILE+TILE/2}));\n}\n\n/* ── INPUT ── */\nwindow.addEventListener('keydown',e=>{\n  GS.keys[e.code]=true;\n  if(e.code==='KeyE'){e.preventDefault();tryInteract();}\n  if(e.code==='Space'){e.preventDefault();tryAttack();}\n  if(e.code==='KeyB') toggleDrone();\n  if(e.code==='KeyV') toggleWardrobe();\n  Object.entries(TECH_DEF).forEach(([id,tech])=>{\n    if(e.code===tech.key&&GS.techs[id]&&GS.running&&!GS.paused) tech.act();\n  });\n  if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)) e.preventDefault();\n});\nwindow.addEventListener('keyup',e=>{GS.keys[e.code]=false;});\n\n/* ── PLAYER UPDATE ── */\nfunction updatePlayer(dt){\n  const P=GS.player;\n  if(GS.paused) return;\n  const spd=(P.hasDrone?210:150)*dt;\n  let dx=0,dy=0;\n  if(GS.keys['KeyW']||GS.keys['ArrowUp']) dy=-1;\n  if(GS.keys['KeyS']||GS.keys['ArrowDown']) dy=1;\n  if(GS.keys['KeyA']||GS.keys['ArrowLeft']) dx=-1;\n  if(GS.keys['KeyD']||GS.keys['ArrowRight']) dx=1;\n  if(dx||dy){const m=Math.hypot(dx,dy);dx/=m;dy/=m;P.dir=Math.atan2(dy,dx);}\n  const nx=P.x+dx*spd,ny=P.y+dy*spd;\n  if(!isSolid(nx,P.y)) P.x=nx;\n  if(!isSolid(P.x,ny)) P.y=ny;\n  P.x=Math.max(TILE,Math.min(WORLD_W*TILE-TILE,P.x));\n  P.y=Math.max(TILE,Math.min(WORLD_H*TILE-TILE,P.y));\n  if(P.swordTimer>0) P.swordTimer-=dt;\n  if(P.invTimer>0) P.invTimer-=dt;\n  GS.camera.x=P.x-W/2;GS.camera.y=P.y-H/2;\n  // trail\n  if(GS.cosmetics.trail&&(dx||dy)){\n    const tc={trail_fire:['#f39c12','#e74c3c','#ff8800'],trail_ice:['#64c8ff','#b8e8ff','#fff'],trail_star:['#fff700','#ffe000','#ffff88']};\n    const cols=tc[GS.cosmetics.trail]||['#fff'];\n    if(Math.random()<0.4) spawnP(P.x,P.y,cols[Math.floor(Math.random()*cols.length)],1);\n  }\n}\n\nfunction isSolid(wx,wy){\n  const tx=Math.floor(wx/TILE),ty=Math.floor(wy/TILE);\n  if(tx<0||ty<0||tx>=WORLD_W||ty>=WORLD_H) return true;\n  const t=world[ty][tx];\n  if(GS.player.hasDrone&&(t===0||t===8||t===9)) return false;\n  return TD[t]?.solid||false;\n}\n\nfunction killShark(s){\n  if(s.dead) return;\n  s.dead=true;s.hp=0;s.respawnTimer=0;\n  GS.kills++;SDK.progress('meca_tiburones',GS.kills);SDK.setStat('Tiburones derrotados',GS.kills);\n  document.getElementById('kv').textContent=GS.kills;\n  spawnP(s.x,s.y,'#f39c12',14);\n}\n\n/* ── SHARKS UPDATE (with respawn) ── */\nconst RESPAWN_TIME=45;\nfunction updateSharks(dt){\n  if(GS.paused) return;\n  const P=GS.player;\n  GS.traps=GS.traps.filter(t=>{t.life-=dt;return t.life>0;});\n  GS.sharks.forEach(s=>{\n    if(s.dead){\n      s.respawnTimer+=dt;\n      if(s.respawnTimer>=RESPAWN_TIME){\n        s.dead=false;s.hp=s.maxHp;\n        s.x=s.spawnX;s.y=s.spawnY;\n        s.respawnTimer=0;\n        spawnP(s.x,s.y,'#e74c3c',8);\n        showNotif('Un tiburon ha reaparecido!');\n      }\n      return;\n    }\n    if(s.hitTimer>0) s.hitTimer-=dt;\n    if(s.slowTimer>0) s.slowTimer-=dt;\n    if(s.wallCooldown>0) s.wallCooldown-=dt;\n    s.floatOff+=dt*2;\n    const dx=P.x-s.x,dy=P.y-s.y,dist=Math.hypot(dx,dy);\n    s.state=dist<220?'chase':'patrol';\n    const spd=s.speed*(s.slowTimer>0?0.3:1);\n    if(s.state==='patrol'){\n      // Change direction only every 1.5-3 s, not every frame\n      s.patrolTimer=(s.patrolTimer||0)-dt;\n      if(s.patrolTimer<=0){\n        s.angle+=(Math.random()-0.5)*Math.PI;\n        s.patrolTimer=1.5+Math.random()*1.5;\n      }\n      s.vx=Math.cos(s.angle)*spd;s.vy=Math.sin(s.angle)*spd;\n    } else {\n      s.vx=(dx/dist)*spd*1.4;s.vy=(dy/dist)*spd*1.4;\n    }\n    GS.traps.forEach(tr=>{if(Math.hypot(s.x-tr.x,s.y-tr.y)<60) s.slowTimer=3;});\n    const ttx=Math.floor((s.x+s.vx)/TILE),tty=Math.floor((s.y+s.vy)/TILE);\n    const tt=world[tty]?.[ttx];\n    if(tt===undefined||tt===0||tt===8||tt===9){\n      // Only bounce once per 0.4 s — prevents per-frame spinning at 60 Hz\n      if(s.wallCooldown<=0){\n        const homeAngle=Math.atan2(s.spawnY-s.y,s.spawnX-s.x);\n        s.angle=homeAngle+(Math.random()-0.5)*Math.PI*0.8;\n        s.patrolTimer=1;\n        s.wallCooldown=0.4;\n      }\n    } else{s.x+=s.vx;s.y+=s.vy;}\n    if(dist<28&&P.invTimer<=0){\n      if(GS.shieldActive){\n        GS.shieldActive=false;spawnP(P.x,P.y,'#2196f3',12);\n        P.invTimer=1;showNotif('Escudo bloqueo el golpe');\n      } else {\n        P.hp=Math.max(0,P.hp-10);P.invTimer=1.5;\n        updateHUD();camShake=0.4;spawnP(P.x,P.y,'#e74c3c',8);\n        if(P.hp<=0) triggerGameOver();\n      }\n    }\n  });\n}\n\n/* ── WHALES UPDATE ── */\nfunction updateWhales(dt){\n  if(GS.paused) return;\n  GS.whales.forEach(w=>{\n    w.floatOff+=dt*1.5;\n    w.angle+=dt*(Math.random()-0.5)*0.5;\n    const vx=Math.cos(w.angle)*w.speed,vy=Math.sin(w.angle)*w.speed;\n    const nx=w.x+vx,ny=w.y+vy;\n    const ttx=Math.floor(nx/TILE),tty=Math.floor(ny/TILE);\n    const tt=world[tty]?.[ttx];\n    if(tt===0){w.x=nx;w.y=ny;}\n    else{w.angle+=Math.PI/2+Math.random()*0.5;}\n    w.x=Math.max(0,Math.min(WORLD_W*TILE,w.x));\n    w.y=Math.max(0,Math.min(WORLD_H*TILE,w.y));\n  });\n}\n\nfunction tryAttack(){\n  if(!GS.running||GS.paused) return;\n  GS.player.swordTimer=0.35;\n  const P=GS.player;\n  const ax=P.x+Math.cos(P.dir)*38,ay=P.y+Math.sin(P.dir)*38;\n  GS.sharks.forEach(s=>{\n    if(s.dead||Math.hypot(s.x-ax,s.y-ay)>44) return;\n    s.hp--;s.hitTimer=0.3;spawnP(s.x,s.y,'#e74c3c',6);\n    if(s.hp<=0){killShark(s);showNotif('Tiburon derrotado');}\n  });\n}\n\nfunction tryInteract(){\n  if(!GS.running||GS.paused) return;\n  const P=GS.player;\n  // Guarida de Bombón en Selvarrón\n  if(Math.hypot(P.x-LAIR.x,P.y-LAIR.y)<2.5*TILE){\n    if(GS.doneChallenges.size>=LAIR.need){bossPractice=false;bossFromWorld=true;saveGame();_openBossScreen();}\n    else showNotif('La guarida está sellada: completa '+LAIR.need+' retos ('+GS.doneChallenges.size+'/'+LAIR.need+')');\n    return;\n  }\n  // Shop on market island\n  if(Math.hypot(P.x-61*TILE,P.y-72*TILE)<5*TILE){openShop();return;}\n  // Whales\n  let whaleTalked=false;\n  GS.whales.forEach(w=>{\n    if(!whaleTalked&&Math.hypot(P.x-w.x,P.y-w.y)<80){\n      const msgs=['¡QUAAACK! (La ballena te saluda)','¡El oceano es enorme! Explora mas.','¿Sabias que las ballenas se comunican por sonido?','¡Sigue explorando las islas!'];\n      showNotif(msgs[Math.floor(Math.random()*msgs.length)]);\n      whaleTalked=true;\n    }\n  });\n  if(whaleTalked) return;\n  // Challenges\n  GS.challenges.forEach(ch=>{\n    if(GS.doneChallenges.has(ch.id)) return;\n    if(Math.hypot(P.x-ch.wx,P.y-ch.wy)<52) openChallengeDiff(ch);\n  });\n}\n\nfunction spawnP(x,y,color,n){\n  for(let i=0;i<n;i++){\n    const a=Math.random()*Math.PI*2,sp=1+Math.random()*3;\n    GS.particles.push({x,y,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,life:0.9+Math.random()*0.4,maxLife:1,color,r:2+Math.random()*3});\n  }\n}\nfunction updateParticles(dt){\n  GS.particles=GS.particles.filter(p=>{p.x+=p.vx;p.y+=p.vy;p.vy+=0.08;p.life-=dt;return p.life>0;});\n}\n\n\n/* ── DECORATIONS (pixel art sprites) ── */\nconst DECOR=[];\nfunction initDecor(){\n  DECOR.length=0;\n  // biome -> array of {img, w, h, prob}\n  const bio={\n    1:[{img:treeImg,w:36,h:40,p:0.06},{img:bushImg,w:34,h:22,p:0.07},{img:grassImg,w:28,h:14,p:0.1}],\n    3:[{img:coalImg,w:30,h:28,p:0.08},{img:rockImg,w:34,h:30,p:0.05}],\n    4:[{img:rockImg,w:38,h:32,p:0.09},{img:coalImg,w:26,h:24,p:0.04}],\n    5:[{img:willowImg,w:44,h:38,p:0.06},{img:bushImg,w:30,h:20,p:0.09},{img:grassImg,w:26,h:12,p:0.12}],\n    6:[{img:grassImg,w:22,h:10,p:0.12},{img:bushImg,w:26,h:16,p:0.05}],\n    10:[{img:rockImg,w:28,h:24,p:0.06},{img:coalImg,w:22,h:20,p:0.04}],\n    11:[{img:rockImg,w:32,h:28,p:0.07},{img:grassImg,w:22,h:10,p:0.1}],\n    12:[{img:rockImg,w:30,h:26,p:0.1},{img:coalImg,w:24,h:22,p:0.08}],\n    13:[{img:bushImg,w:28,h:18,p:0.1},{img:grassImg,w:24,h:12,p:0.12}],\n  };\n  // house on market island around tx=61,ty=72\n  DECOR.push({x:61*TILE+10,y:72*TILE-10,img:houseImg,w:52,h:46,fixed:true});\n  for(let ty=0;ty<WORLD_H;ty++) for(let tx=0;tx<WORLD_W;tx++){\n    const t=world[ty][tx];\n    if(!bio[t]) continue;\n    bio[t].forEach(({img,w,h,p})=>{\n      if(Math.random()<p){\n        DECOR.push({\n          x:tx*TILE+8+Math.random()*(TILE-16),\n          y:ty*TILE+8+Math.random()*(TILE-16),\n          img,w,h,\n          s:0.7+Math.random()*0.5,\n        });\n      }\n    });\n  }\n}\n\n/* ── HAT DRAWING ── */\nfunction drawHat(hatId,cx,cy){\n  const s=11;\n  ctx.save();ctx.textAlign='center';ctx.textBaseline='middle';\n  switch(hatId){\n    case 'hat_pirate':\n      ctx.fillStyle='#111';\n      ctx.beginPath();ctx.ellipse(cx,cy-s*0.3,s*1.3,s*0.35,0,0,Math.PI*2);ctx.fill();\n      ctx.fillRect(cx-s*0.7,cy-s*1.5,s*1.4,s*1.2);\n      ctx.fillStyle='#fff';ctx.font=(s*0.75)+'px serif';ctx.fillText('☠',cx,cy-s*0.9);\n      break;\n    case 'hat_crown':\n      ctx.fillStyle='#f39c12';\n      ctx.beginPath();\n      ctx.moveTo(cx-s,cy-s*0.4);ctx.lineTo(cx-s,cy-s*2);\n      ctx.lineTo(cx-s*0.4,cy-s*1.2);ctx.lineTo(cx,cy-s*2);\n      ctx.lineTo(cx+s*0.4,cy-s*1.2);ctx.lineTo(cx+s,cy-s*2);\n      ctx.lineTo(cx+s,cy-s*0.4);ctx.closePath();ctx.fill();\n      ctx.fillStyle='#e74c3c';\n      ctx.beginPath();ctx.arc(cx,cy-s*1.75,s*0.18,0,Math.PI*2);ctx.fill();\n      break;\n    case 'hat_cowboy':\n      ctx.fillStyle='#8B4513';\n      ctx.beginPath();ctx.ellipse(cx,cy-s*0.2,s*1.7,s*0.36,0,0,Math.PI*2);ctx.fill();\n      ctx.fillRect(cx-s*0.85,cy-s*1.7,s*1.7,s*1.5);\n      ctx.strokeStyle='#f39c12';ctx.lineWidth=2;\n      ctx.beginPath();ctx.moveTo(cx-s*0.85,cy-s*0.8);ctx.lineTo(cx+s*0.85,cy-s*0.8);ctx.stroke();\n      break;\n    case 'hat_party':\n      ctx.fillStyle='#e74c3c';\n      ctx.beginPath();ctx.moveTo(cx,cy-s*2.6);ctx.lineTo(cx-s*0.8,cy-s*0.4);ctx.lineTo(cx+s*0.8,cy-s*0.4);ctx.closePath();ctx.fill();\n      ctx.fillStyle='#f9e079';ctx.font=(s*0.6)+'px serif';ctx.fillText('⭐',cx,cy-s*2.2);\n      break;\n    case 'hat_tophat':\n      ctx.fillStyle='#1a1a1a';\n      ctx.beginPath();ctx.ellipse(cx,cy-s*0.25,s*1.2,s*0.3,0,0,Math.PI*2);ctx.fill();\n      ctx.fillRect(cx-s*0.72,cy-s*1.9,s*1.44,s*1.65);\n      ctx.strokeStyle='#777';ctx.lineWidth=1.5;\n      ctx.beginPath();ctx.moveTo(cx-s*0.72,cy-s*1.5);ctx.lineTo(cx+s*0.72,cy-s*1.5);ctx.stroke();\n      break;\n  }\n  ctx.restore();\n}\n\n/* ── ISLAND / TECH DETECTION ── */\nlet camShake=0,lastIsland='';\nfunction detectIsland(){\n  const P=GS.player;let found='';\n  ISLANDS.forEach(isl=>{if(Math.hypot(P.x-isl.cx,P.y-isl.cy)<13*TILE){found=isl.name;\n    if(!GS.visited.has(isl.id)){GS.visited.add(isl.id);if(GS.visited.size>=ISLANDS.length) SDK.unlock('meca_islas');saveGame();}}});\n  if(found!==lastIsland){\n    lastIsland=found;\n    if(found){const lb=document.getElementById('ilabel');lb.textContent=found;lb.style.opacity='1';setTimeout(()=>lb.style.opacity='0',2200);}\n  }\n  const pfxMap={clouds:'cl',central:'c',volcano:'v',mountain:'m',swamp:'s',desert:'d',arctic:'i',coral:'co',jungle:'j'};\n  ISLANDS.forEach(isl=>{\n    if(GS.techs[isl.id]||isl.id==='market'||isl.id==='jungle') return;\n    const pfx=pfxMap[isl.id]||isl.id[0];\n    if([...GS.doneChallenges].some(id=>id.replace(/\\d+$/,'')===pfx)) unlockTech(isl.id);\n  });\n}\nfunction unlockTech(id){\n  if(GS.techs[id]||!TECH_DEF[id]) return;\n  GS.techs[id]=true;\n  document.getElementById('ts-'+id)?.classList.add('unlocked');\n  showNotif('Tecnologia desbloqueada: '+TECH_DEF[id].name);\n}\n\n/* ── HUD ── */\nfunction updateHUD(){\n  const P=GS.player;\n  const hp=Math.max(0,P.hp);\n  document.getElementById('hv').textContent=hp;\n  document.getElementById('hf').style.width=(Math.min(150,hp)/150*100)+'%';\n  document.getElementById('hf').style.background=hp>50?'linear-gradient(90deg,#27ae60,#2ecc71)':hp>25?'linear-gradient(90deg,#f39c12,#e67e22)':'linear-gradient(90deg,#e74c3c,#c0392b)';\n  document.getElementById('sv').textContent=GS.stars;\n  document.getElementById('dv').textContent=GS.doneChallenges.size;\n  document.getElementById('dst').textContent=P.hasDrone?'Dron activo':'Sin dron';\n  const row=document.getElementById('invrow');\n  if(!GS.inventory.length){row.innerHTML='<span style=\"color:#555;font-size:9px;\">vacio</span>';return;}\n  const c={};GS.inventory.forEach(i=>{c[i]=(c[i]||0)+1;});\n  row.innerHTML=Object.entries(c).map(([k,v])=>`<span class=\"itag\">${k}${v>1?' x'+v:''}</span>`).join('');\n}\n\n\n/* ── RENDER ── */\nfunction drawSprite(img,x,y,w,h,flipX,alpha,tint){\n  ctx.save();ctx.globalAlpha=alpha||1;ctx.translate(x,y);\n  if(flipX) ctx.scale(-1,1);\n  if(img.complete&&img.naturalWidth>0) ctx.drawImage(img,-w/2,-h/2,w,h);\n  if(tint){ctx.globalCompositeOperation='source-atop';ctx.fillStyle=tint;ctx.fillRect(-w/2,-h/2,w,h);ctx.globalCompositeOperation='source-over';}\n  ctx.restore();ctx.globalAlpha=1;\n}\n\nfunction render(){\n  ctx.clearRect(0,0,W,H);\n  let cx=GS.camera.x,cy=GS.camera.y;\n  if(camShake>0){cx+=Math.sin(Date.now()*0.1)*(camShake*6);cy+=Math.cos(Date.now()*0.13)*(camShake*5);}\n  camShake=Math.max(0,camShake-0.016);\n  const stx=Math.floor(cx/TILE),sty=Math.floor(cy/TILE);\n  for(let ty=sty;ty<Math.ceil((cy+H)/TILE)+1;ty++){\n    for(let tx=stx;tx<Math.ceil((cx+W)/TILE)+1;tx++){\n      if(ty<0||tx<0||ty>=WORLD_H||tx>=WORLD_W){ctx.fillStyle='#071a2e';ctx.fillRect(tx*TILE-cx,ty*TILE-cy,TILE,TILE);continue;}\n      const t=world[ty][tx],d=TD[t]||TD[0];\n      ctx.fillStyle=d.c;ctx.fillRect(tx*TILE-cx,ty*TILE-cy,TILE,TILE);\n      ctx.strokeStyle=d.b;ctx.lineWidth=0.5;ctx.strokeRect(tx*TILE-cx+0.5,ty*TILE-cy+0.5,TILE-1,TILE-1);\n      if(t===0){ctx.fillStyle=`rgba(255,255,255,${0.03+0.02*Math.sin(Date.now()*0.001+tx+ty)})`;ctx.fillRect(tx*TILE-cx,ty*TILE-cy,TILE,TILE);}\n      if(t===8){ctx.fillStyle=`rgba(255,100,0,${0.2+0.15*Math.sin(Date.now()*0.003+tx*0.5)})`;ctx.fillRect(tx*TILE-cx,ty*TILE-cy,TILE,TILE);}\n      if(t===11){ctx.fillStyle=`rgba(200,230,255,${0.15+0.1*Math.sin(Date.now()*0.002+tx+ty)})`;ctx.fillRect(tx*TILE-cx,ty*TILE-cy,TILE,TILE);}\n    }\n  }\n  // Decor\n  DECOR.forEach(d=>{\n    const sx=d.x-cx,sy=d.y-cy;\n    if(sx<-80||sx>W+80||sy<-80||sy>H+80) return;\n    const sc=d.s||1;\n    ctx.save();ctx.globalAlpha=d.fixed?0.92:0.8;\n    if(d.img&&d.img.complete&&d.img.naturalWidth>0)\n      ctx.drawImage(d.img,sx-d.w*sc/2,sy-d.h*sc/2,d.w*sc,d.h*sc);\n    ctx.restore();\n  });\n  ctx.globalAlpha=1;\n  // Traps\n  GS.traps.forEach(tr=>{\n    ctx.font='18px serif';ctx.textAlign='center';ctx.textBaseline='middle';\n    ctx.globalAlpha=Math.min(1,tr.life/2);ctx.fillText('🪤',tr.x-cx,tr.y-cy);ctx.globalAlpha=1;\n    ctx.strokeStyle='rgba(255,200,0,0.2)';ctx.lineWidth=1;\n    ctx.beginPath();ctx.arc(tr.x-cx,tr.y-cy,60,0,Math.PI*2);ctx.stroke();\n  });\n  // Respawn indicators\n  GS.sharks.forEach(s=>{\n    if(!s.dead||s.respawnTimer<RESPAWN_TIME-6) return;\n    const sx=s.spawnX-cx,sy=s.spawnY-cy;\n    if(sx<-60||sx>W+60||sy<-60||sy>H+60) return;\n    const p=(s.respawnTimer-(RESPAWN_TIME-6))/6;\n    ctx.globalAlpha=p*0.7;\n    const r=22+Math.sin(Date.now()*0.008)*6;\n    ctx.strokeStyle='#e74c3c';ctx.lineWidth=2;\n    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.stroke();\n    ctx.font='16px serif';ctx.textAlign='center';ctx.textBaseline='middle';\n    ctx.fillText('❗',sx,sy);ctx.globalAlpha=1;\n  });\n  // Challenges\n  GS.challenges.forEach(ch=>{\n    const sx=ch.wx-cx,sy=ch.wy-cy;\n    if(sx<-60||sx>W+60||sy<-60||sy>H+60) return;\n    if(GS.doneChallenges.has(ch.id)){\n      ctx.globalAlpha=0.5;ctx.font='20px serif';ctx.textAlign='center';ctx.textBaseline='middle';\n      ctx.fillText('✅',sx,sy);ctx.globalAlpha=1;return;\n    }\n    const pulse=0.5+0.5*Math.sin(Date.now()*0.004);\n    ctx.beginPath();ctx.arc(sx,sy,22+pulse*6,0,Math.PI*2);\n    ctx.strokeStyle=`rgba(255,200,0,${0.3+pulse*0.4})`;ctx.lineWidth=2;ctx.stroke();\n    ctx.font='22px serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(ch.icon,sx,sy);\n    ctx.font='bold 9px Nunito,sans-serif';ctx.fillStyle='#fff';ctx.fillText('[E] '+ch.title,sx,sy+26);\n    if(Math.hypot(GS.player.x-ch.wx,GS.player.y-ch.wy)<52){\n      ctx.fillStyle='rgba(10,10,30,0.85)';\n      ctx.beginPath();\n      if(ctx.roundRect) ctx.roundRect(sx-46,sy-50,92,18,5); else ctx.rect(sx-46,sy-50,92,18);\n      ctx.fill();\n      ctx.font='bold 9px Nunito,sans-serif';ctx.fillStyle='#f9e079';ctx.fillText('Presiona E',sx,sy-39);\n    }\n  });\n  // Shop indicator on market island\n  const shopX=61*TILE+TILE/2-cx,shopY=72*TILE-cy;\n  if(Math.hypot(GS.player.x-61*TILE,GS.player.y-72*TILE)<5*TILE) floatLabel(shopX,shopY-48,'🏪 TIENDA — Presiona E','#f9e079');\n  drawLair(cx,cy);\n  // Particles\n  GS.particles.forEach(p=>{\n    ctx.globalAlpha=p.life/p.maxLife;ctx.fillStyle=p.color;\n    ctx.beginPath();ctx.arc(p.x-cx,p.y-cy,p.r,0,Math.PI*2);ctx.fill();\n  });\n  ctx.globalAlpha=1;\n  // Whales\n  GS.whales.forEach(w=>{\n    const sx=w.x-cx,sy=w.y-cy;\n    if(sx<-80||sx>W+80||sy<-80||sy>H+80) return;\n    const bob=Math.sin(w.floatOff)*3;\n    ctx.fillStyle='rgba(0,30,80,0.2)';ctx.beginPath();ctx.ellipse(sx,sy+bob+14,26,7,0,0,Math.PI*2);ctx.fill();\n    const flipW=Math.cos(w.angle)<0;\n    ctx.save();ctx.globalAlpha=0.88;\n    if(whaleImg.complete&&whaleImg.naturalWidth>0)\n      drawSprite(whaleImg,sx,sy+bob,60,38,flipW);\n    ctx.restore();\n    // interaction prompt\n    if(Math.hypot(GS.player.x-w.x,GS.player.y-w.y)<80){\n      ctx.fillStyle='rgba(10,10,30,0.85)';\n      ctx.beginPath();\n      if(ctx.roundRect) ctx.roundRect(sx-40,sy-52,80,16,5); else ctx.rect(sx-40,sy-52,80,16);\n      ctx.fill();\n      ctx.font='bold 9px Nunito,sans-serif';ctx.fillStyle='#64c8ff';ctx.textAlign='center';ctx.fillText('[E] Saludar',sx,sy-41);\n    }\n  });\n  // Sharks\n  GS.sharks.forEach(s=>{\n    if(s.dead) return;\n    const sx=s.x-cx,sy=s.y-cy;\n    if(sx<-70||sx>W+70||sy<-70||sy>H+70) return;\n    const bob=Math.sin(s.floatOff)*3;\n    ctx.fillStyle='rgba(0,0,0,0.22)';ctx.beginPath();ctx.ellipse(sx,sy+bob+12,20,6,0,0,Math.PI*2);ctx.fill();\n    const tint=s.hitTimer>0?'rgba(255,80,80,0.65)':s.slowTimer>0?'rgba(100,200,255,0.5)':null;\n    drawSprite(sharkImg,sx,sy+bob,52,36,s.vx<0,1,tint);\n    if(s.hp<s.maxHp){\n      const bw=34;ctx.fillStyle='#333';ctx.fillRect(sx-bw/2,sy-30,bw,5);\n      ctx.fillStyle='#e74c3c';ctx.fillRect(sx-bw/2,sy-30,(s.hp/s.maxHp)*bw,5);\n    }\n  });\n  // Player\n  const P=GS.player;const px=P.x-cx,py=P.y-cy;\n  ctx.fillStyle='rgba(0,0,0,0.2)';ctx.beginPath();ctx.ellipse(px,py+14,14,5,0,0,Math.PI*2);ctx.fill();\n  if(GS.shieldActive){\n    ctx.strokeStyle=`rgba(33,150,243,${0.5+0.3*Math.sin(Date.now()*0.008)})`;\n    ctx.lineWidth=3;ctx.beginPath();ctx.arc(px,py,28,0,Math.PI*2);ctx.stroke();\n  }\n  if(P.hasDrone){\n    ctx.save();ctx.translate(px,py);const da=Date.now()*0.005;\n    for(let i=0;i<4;i++){\n      const pa=da+i*Math.PI/2,bx=Math.cos(pa)*20,by=Math.sin(pa)*20-8;\n      ctx.fillStyle='rgba(150,220,255,0.65)';ctx.save();ctx.translate(bx,by);ctx.rotate(da*3);\n      ctx.beginPath();ctx.ellipse(0,0,7,2,0,0,Math.PI*2);ctx.fill();ctx.restore();\n    }\n    ctx.restore();\n  }\n  const flip=!(P.dir>Math.PI/2||P.dir<-Math.PI/2);\n  const alpha=P.invTimer>0&&Math.floor(P.invTimer*10)%2===0?0.3:1;\n  const skinTint=GS.cosmetics.skin?SKIN_TINTS[GS.cosmetics.skin]:null;\n  drawSprite(duckImg,px,py,36,36,flip,alpha,skinTint);\n  if(GS.cosmetics.hat) drawHat(GS.cosmetics.hat,px,py-14);\n  if(P.swordTimer>0){\n    const prog=1-(P.swordTimer/0.35);\n    ctx.save();ctx.translate(px,py);ctx.rotate(P.dir-Math.PI/4+prog*Math.PI/1.2);\n    ctx.fillStyle='#c0c0c0';ctx.fillRect(16,-3,28,5);\n    ctx.fillStyle='#f39c12';ctx.fillRect(12,-5,8,9);\n    ctx.strokeStyle='rgba(255,220,100,0.55)';ctx.lineWidth=3;\n    ctx.beginPath();ctx.arc(0,0,34,-Math.PI/4,prog*Math.PI/1.2-Math.PI/4);ctx.stroke();\n    ctx.restore();\n  }\n}\n\n\nfunction floatLabel(x,y,text,color){\n  ctx.font='bold 10px Nunito,sans-serif';const w=ctx.measureText(text).width+16;\n  ctx.fillStyle='rgba(10,10,30,0.85)';ctx.fillRect(x-w/2,y-12,w,18);\n  ctx.fillStyle=color||'#fff';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,x,y-3);\n}\nfunction drawLair(cx,cy){\n  const sx=LAIR.x-cx,sy=LAIR.y-cy;\n  if(sx<-120||sx>W+120||sy<-120||sy>H+120) return;\n  const open=GS.doneChallenges.size>=LAIR.need,t=Date.now()*0.004;\n  ctx.save();ctx.translate(sx,sy);\n  for(let i=0;i<3;i++){ctx.strokeStyle=open?`rgba(231,76,60,${0.6-i*0.18})`:'rgba(120,120,140,0.4)';ctx.lineWidth=3;\n    ctx.beginPath();ctx.arc(0,0,22+i*9+(open?Math.sin(t+i)*3:0),0,Math.PI*2);ctx.stroke();}\n  ctx.fillStyle=open?'rgba(120,10,10,0.75)':'rgba(40,40,50,0.8)';ctx.beginPath();ctx.arc(0,0,20,0,Math.PI*2);ctx.fill();\n  ctx.font='20px serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(open?'☠':'🔒',0,1);\n  ctx.restore();\n  if(Math.hypot(GS.player.x-LAIR.x,GS.player.y-LAIR.y)<2.5*TILE)\n    floatLabel(sx,sy-54,open?'☠ GUARIDA DE BOMBÓN — Presiona E':'Sellada: '+GS.doneChallenges.size+'/'+LAIR.need+' retos',open?'#ff8a80':'#aaa');\n}\n\n/* ── CHALLENGE SYSTEM ── */\nlet activeChallenge=null,selectedDiff=1;\nlet _challengeTimerInterval=null,_challengeTimeLeft=0;\n\nfunction openChallengeDiff(ch){\n  activeChallenge=ch;GS.paused=true;\n  document.getElementById('ch-d-title').textContent=ch.title;\n  document.getElementById('ch-diff').classList.add('vis');\n  document.getElementById('ch-theory').classList.remove('vis');\n  document.getElementById('ch-game').classList.remove('vis');\n  document.getElementById('ch-scr').classList.remove('hidden');\n}\nfunction selectDiff(d){\n  selectedDiff=d;\n  document.getElementById('ch-diff').classList.remove('vis');\n  // Hard mode: skip theory\n  if(d===3){\n    goToChallenge();\n  } else {\n    const ch=activeChallenge;\n    document.getElementById('ch-t-title').textContent=ch.theory.h;\n    document.getElementById('ch-t-body').innerHTML=ch.theory.body;\n    document.getElementById('ch-theory').classList.add('vis');\n  }\n}\nfunction goToChallenge(){\n  const ch=activeChallenge;\n  document.getElementById('ch-theory').classList.remove('vis');\n  document.getElementById('ch-game').classList.add('vis');\n  document.getElementById('ch-g-title').textContent=ch.title+' — '+(selectedDiff===1?'FACIL':selectedDiff===2?'NORMAL':'DIFICIL');\n  document.getElementById('ch-g-result').textContent='';\n  document.getElementById('ch-g-close').style.display='none';\n  const c=document.getElementById('ch-g-content');c.innerHTML='';\n  // Get challenge content for this difficulty\n  let cv;\n  if(ch.variants){cv=ch.variants.find(v=>v.diff===selectedDiff)||ch.variants[0];}\n  else{cv={type:ch.type,q:ch.q,opts:ch.opts,ans:ch.ans,items:ch.items,correct:ch.correct,pairs:ch.pairs,stars:ch.stars};}\n  activeChallenge._cv=cv;\n  if(cv.type==='quiz') buildQuiz(cv,c);\n  else if(cv.type==='sequence') buildSequence(cv,c);\n  else buildMatch(cv,c);\n  // Timer\n  stopTimer();\n  const timeLimit=selectedDiff===2?45:selectedDiff===3?25:0;\n  if(timeLimit>0) startTimer(timeLimit);\n}\nfunction startTimer(secs){\n  _challengeTimeLeft=secs;\n  const tb=document.getElementById('timer-bar');\n  const ti=document.getElementById('timer-inner');\n  tb.style.display='block';ti.textContent=secs;\n  _challengeTimerInterval=setInterval(()=>{\n    _challengeTimeLeft--;\n    ti.textContent=_challengeTimeLeft;\n    if(_challengeTimeLeft<=0){stopTimer();finalizeChallenge(false);}\n  },1000);\n}\nfunction stopTimer(){\n  if(_challengeTimerInterval){clearInterval(_challengeTimerInterval);_challengeTimerInterval=null;}\n  document.getElementById('timer-bar').style.display='none';\n}\nfunction closeChallenge(){\n  stopTimer();\n  document.getElementById('ch-scr').classList.add('hidden');\n  ['ch-diff','ch-theory','ch-game'].forEach(id=>document.getElementById(id).classList.remove('vis'));\n  GS.paused=false;activeChallenge=null;\n}\n\n/* QUIZ */\nlet _qa=false;\nfunction buildQuiz(cv,c){\n  _qa=false;\n  document.getElementById('ch-g-desc').textContent='Elige la respuesta correcta:';\n  c.innerHTML=`<p style=\"font-size:12px;font-weight:800;color:#fff;margin-bottom:8px;\">${cv.q}</p>\n    <div class=\"fopts\">${cv.opts.map((o,i)=>`<div class=\"fopt\" id=\"qo${i}\" onclick=\"answerQuiz(${i})\">${o}</div>`).join('')}</div>`;\n}\nfunction answerQuiz(idx){\n  if(_qa) return;_qa=true;stopTimer();\n  const cv=activeChallenge._cv,ok=idx===cv.ans;\n  document.getElementById('qo'+idx).classList.add(ok?'correct':'wrong');\n  if(!ok) document.getElementById('qo'+cv.ans).classList.add('correct');\n  finalizeChallenge(ok);\n}\n\n/* SEQUENCE — FIXED BUG: track original indices through shuffle */\nlet _sd=-1,_ss=null;\nfunction buildSequence(cv,c){\n  document.getElementById('ch-g-desc').textContent=cv.prompt||'Ordena los elementos:';\n  // Fisher-Yates shuffle tracking original indices\n  const origIdx=cv.items.map((_,i)=>i);\n  for(let i=origIdx.length-1;i>0;i--){\n    const j=Math.floor(Math.random()*(i+1));\n    [origIdx[i],origIdx[j]]=[origIdx[j],origIdx[i]];\n  }\n  const shuffled=origIdx.map(i=>cv.items[i]);\n  _ss={cv,shuffled,origIdx,placed:[]};\n  renderSeq(c);\n}\nfunction renderSeq(c){\n  const {shuffled,placed}=_ss;\n  c.innerHTML=`\n    <div style=\"font-size:10px;color:#aaa;margin-bottom:4px;\">Banco — arrastra al area de orden:</div>\n    <div class=\"seq-bank\">${shuffled.map((item,i)=>placed.includes(i)?'':\n      `<div class=\"sitem\" draggable=\"true\" id=\"si${i}\" ondragstart=\"seqDS(${i})\">${item}</div>`).join('')||\n      '<span style=\"color:#555;font-size:10px;\">Todos colocados</span>'}</div>\n    <div style=\"font-size:10px;color:#aaa;margin:4px 0;\">Orden:</div>\n    <div class=\"seq-drop\" id=\"sdrop\"\n      ondragover=\"event.preventDefault();document.getElementById('sdrop').classList.add('dragover')\"\n      ondragleave=\"document.getElementById('sdrop').classList.remove('dragover')\"\n      ondrop=\"seqDrop(event)\">\n      ${placed.map(i=>`<div class=\"sitem placed\">${_ss.shuffled[i]}</div>`).join('')||\n        '<span style=\"color:#555;font-size:10px;\">Arrastra aqui...</span>'}\n    </div>\n    <button class=\"btn grn\" onclick=\"checkSeq()\" style=\"margin-top:8px;\">VERIFICAR</button>`;\n}\nfunction seqDS(i){_sd=i;}\nfunction seqDrop(e){\n  e.preventDefault();document.getElementById('sdrop').classList.remove('dragover');\n  if(_sd<0) return;\n  if(!_ss.placed.includes(_sd)){_ss.placed.push(_sd);renderSeq(document.getElementById('ch-g-content'));}\n  _sd=-1;\n}\nfunction checkSeq(){\n  const {cv,origIdx,placed}=_ss;\n  if(placed.length<cv.items.length){document.getElementById('ch-g-result').innerHTML='<span style=\"color:#f39c12;\">Coloca todas las piezas primero.</span>';return;}\n  // placed[pos] = index into shuffled; origIdx[shuffledIdx] = original item index\n  const ok=placed.every((shuffledIdx,pos)=>cv.correct[pos]===origIdx[shuffledIdx]);\n  stopTimer();finalizeChallenge(ok);\n}\n\n/* MATCH */\nlet _ms=null;\nfunction buildMatch(cv,c){\n  document.getElementById('ch-g-desc').textContent='Empareja cada concepto:';\n  const right=[...cv.pairs.map(p=>p[1])].sort(()=>Math.random()-0.5);\n  _ms={cv,pairs:cv.pairs,right,selLeft:-1,matched:new Set()};\n  renderMatch(c);\n}\nfunction renderMatch(c){\n  const {pairs,right,selLeft,matched}=_ms;\n  c.innerHTML=`<div class=\"match-row\">\n    <div class=\"match-col\"><div class=\"mh\">CONCEPTO</div>\n      ${pairs.map((p,i)=>`<div class=\"mitem ${matched.has(i)?'matched':selLeft===i?'sel':''}\" onclick=\"${matched.has(i)?'':`ML(${i})`}\">${p[0]}</div>`).join('')}\n    </div>\n    <div class=\"match-col\"><div class=\"mh\">RESPUESTA</div>\n      ${right.map((r,i)=>{const isM=pairs.some((p,pi)=>p[1]===r&&matched.has(pi));\n        return `<div class=\"mitem ${isM?'matched':''}\" id=\"mr${i}\" onclick=\"${isM?'':`MR(${i},'${r.replace(/'/g,\"\\\\'\")}')`}\">${r}</div>`;}).join('')}\n    </div>\n  </div><div style=\"font-size:10px;color:#aaa;margin-top:5px;\">Emparejados: ${matched.size}/${pairs.length}</div>`;\n  if(matched.size===pairs.length) setTimeout(()=>{stopTimer();finalizeChallenge(true);},400);\n}\nfunction ML(i){_ms.selLeft=i;renderMatch(document.getElementById('ch-g-content'));}\nfunction MR(i,val){\n  if(_ms.selLeft<0) return;\n  const ok=_ms.pairs[_ms.selLeft][1]===val;\n  if(ok){\n    _ms.matched.add(_ms.selLeft);_ms.selLeft=-1;\n    renderMatch(document.getElementById('ch-g-content'));\n  } else {\n    const li=document.querySelectorAll('.mitem')[_ms.selLeft];\n    const ri=document.getElementById('mr'+i);\n    [li,ri].forEach(el=>{if(el){el.classList.add('flash');setTimeout(()=>el.classList.remove('flash'),700);}});\n    _ms.selLeft=-1;setTimeout(()=>renderMatch(document.getElementById('ch-g-content')),750);\n  }\n}\n\nfunction finalizeChallenge(ok){\n  const ch=activeChallenge,res=document.getElementById('ch-g-result');\n  const cv=ch._cv;\n  const starMult=selectedDiff===1?1:selectedDiff===2?1.5:2;\n  if(ok){\n    const earned=Math.round((cv.stars||2)*starMult);\n    GS.doneChallenges.add(ch.id);addStars(earned);\n    SDK.unlock('meca_primer_reto');\n    if(selectedDiff===3){GS.hardCount++;SDK.progress('meca_dificil',GS.hardCount);}\n    if(GS.doneChallenges.size>=CH_DEFS.length) SDK.unlock('meca_retos');\n    if(GS.doneChallenges.size===LAIR.need) setTimeout(()=>showNotif('☠ La guarida de Bombón se abrió en Selvarrón (sureste)'),1500);\n    SDK.setStat('Retos completados',GS.doneChallenges.size+'/'+CH_DEFS.length);\n    saveGame();\n    if(ch.reward) GS.inventory.push(ch.reward);\n    updateHUD();\n    res.innerHTML=`<span style=\"color:#4caf50;font-weight:800;\">Correcto! +${earned} ⭐${ch.reward?' — '+ch.reward:''}</span>`;\n    showNotif('+'+earned+' estrellas!');\n    const pfxMap={d:'desert',i:'arctic',co:'coral',c:'central',v:'volcano',m:'mountain',s:'swamp',cl:'clouds'};\n    const pfx=ch.id.replace(/\\d+$/,''); // prefijo exacto: 'cl0' es Ventilandia, no Archiparalelo\n    if(pfxMap[pfx]) unlockTech(pfxMap[pfx]);\n    const allParts=DRONE_PARTS.map(p=>p.emoji);\n    if(allParts.every(e=>GS.inventory.includes(e))&&!GS.player.hasDrone)\n      showNotif('Tienes todas las piezas del dron — presiona B');\n  } else {\n    res.innerHTML='<span style=\"color:#e74c3c;\">Incorrecto. Revisa la teoria e intentalo de nuevo.</span>';\n  }\n  document.getElementById('ch-g-close').style.display='inline-block';\n}\n\n\n/* ── DRONE ── */\nfunction toggleDrone(){\n  if(!GS.running) return;\n  const s=document.getElementById('drone-scr');\n  if(!s.classList.contains('hidden')){closeDrone();return;}\n  GS.paused=true;buildDroneUI();s.classList.remove('hidden');\n}\nfunction buildDroneUI(){\n  const avail=DRONE_PARTS.filter(p=>GS.inventory.includes(p.emoji));\n  const used=Object.values(droneAssembled);\n  document.getElementById('plist').innerHTML=avail.map(p=>`\n    <div class=\"pitem ${used.includes(p.emoji)?'used':''}\"\n      draggable=\"${!used.includes(p.emoji)}\"\n      ondragstart=\"dpDS(event,'${p.id}','${p.emoji}','${p.slot}')\">\n      ${p.emoji} ${p.name}\n    </div>`).join('')||'<p style=\"color:#555;font-size:10px;\">Sin piezas. Completa retos primero.</p>';\n  document.getElementById('slarea').innerHTML=DRONE_SLOTS.map(sl=>`\n    <div class=\"dslot ${droneAssembled[sl]?'filled':''}\" id=\"dsl-${sl}\"\n      ondragover=\"event.preventDefault();document.getElementById('dsl-${sl}').classList.add('dragover')\"\n      ondragleave=\"document.getElementById('dsl-${sl}').classList.remove('dragover')\"\n      ondrop=\"dpDrop(event,'${sl}')\">\n      ${droneAssembled[sl]||SLOT_NAMES[sl]}\n    </div>`).join('');\n  const f=Object.keys(droneAssembled).length;\n  document.getElementById('cprog').textContent=f+'/4 piezas';\n  document.getElementById('bassemble').disabled=f<4;\n}\nlet _dp={};\nfunction dpDS(e,id,emoji,slot){_dp={id,emoji,slot};e.dataTransfer.setData('text','p');}\nfunction dropBP(e){e.preventDefault();document.getElementById('bp').classList.remove('dragover');}\nfunction dpDrop(e,target){\n  e.preventDefault();document.getElementById('dsl-'+target).classList.remove('dragover');\n  if(!_dp.emoji) return;\n  if(_dp.slot===target){\n    droneAssembled[target]=_dp.emoji;\n    document.getElementById('cmsg').textContent='Pieza colocada: '+SLOT_NAMES[target];\n  } else {\n    document.getElementById('cmsg').textContent='Esta pieza va en: '+SLOT_NAMES[_dp.slot];\n  }\n  buildDroneUI();\n}\nfunction assembleDrone(){\n  GS.player.hasDrone=true;updateHUD();SDK.unlock('meca_dron');saveGame();\n  showNotif('Dron ensamblado — velocidad +40% y puedes cruzar el oceano');\n  closeDrone();spawnP(GS.player.x,GS.player.y,'#64c8ff',22);\n}\nfunction closeDrone(){document.getElementById('drone-scr').classList.add('hidden');GS.paused=false;}\n\n/* ── SHOP ── */\nlet shopTab='skin';\nfunction openShop(){\n  if(!GS.running) return;\n  GS.paused=true;\n  document.getElementById('shop-stars').textContent=GS.stars;\n  switchShopTab('skin');\n  document.getElementById('shop-scr').classList.remove('hidden');\n}\nfunction closeShop(){document.getElementById('shop-scr').classList.add('hidden');GS.paused=false;}\nfunction switchShopTab(tab){\n  shopTab=tab;\n  document.querySelectorAll('.shop-tab').forEach((t,i)=>{\n    const tabs=['skin','hat','trail'];\n    t.classList.toggle('active',tabs[i]===tab);\n  });\n  renderShopGrid();\n}\nfunction renderShopGrid(){\n  const items=SHOP_ITEMS.filter(it=>it.cat===shopTab);\n  const grid=document.getElementById('shop-grid');\n  grid.innerHTML=items.map(it=>{\n    const owned=GS.cosmetics.owned.has(it.id);\n    return `<div class=\"shop-item ${owned?'owned':''}\" onclick=\"buyItem('${it.id}')\">\n      <span class=\"si-icon\">${it.icon}</span>\n      <span class=\"si-name\">${it.name}</span>\n      <span class=\"si-cost\">${owned?'✅ Obtenido':it.cost+' ⭐'}</span>\n    </div>`;\n  }).join('');\n}\nfunction buyItem(id){\n  const it=SHOP_ITEMS.find(i=>i.id===id);\n  if(!it) return;\n  if(GS.cosmetics.owned.has(id)){showNotif('Ya tienes este objeto');return;}\n  if(GS.stars<it.cost){showNotif('No tienes suficientes estrellas ('+it.cost+' ⭐ necesarias)');return;}\n  GS.stars-=it.cost;GS.cosmetics.owned.add(id);updateHUD();saveGame();\n  document.getElementById('shop-stars').textContent=GS.stars;\n  showNotif('Comprado: '+it.name+'!');renderShopGrid();\n}\n\n/* ── WARDROBE ── */\nfunction toggleWardrobe(){\n  if(!GS.running) return;\n  const s=document.getElementById('wd-scr');\n  if(!s.classList.contains('hidden')){closeWardrobe();return;}\n  GS.paused=true;buildWardrobeUI();s.classList.remove('hidden');\n}\nfunction closeWardrobe(){document.getElementById('wd-scr').classList.add('hidden');GS.paused=false;}\nfunction buildWardrobeUI(){\n  // Equipment slots\n  const slots=[{key:'hat',elId:'eq-hat',iconEl:'eq-hat-icon'},{key:'skin',elId:'eq-skin',iconEl:'eq-skin-icon'},{key:'trail',elId:'eq-trail',iconEl:'eq-trail-icon'}];\n  slots.forEach(({key,elId,iconEl})=>{\n    const eq=GS.cosmetics[key];\n    const el=document.getElementById(elId);\n    el.classList.toggle('has-item',!!eq);\n    const it=eq?SHOP_ITEMS.find(i=>i.id===eq):null;\n    document.getElementById(iconEl).textContent=it?it.icon:'∅';\n  });\n  // Inventory grid\n  const grid=document.getElementById('wd-grid');\n  const owned=[...GS.cosmetics.owned];\n  grid.innerHTML=owned.length?owned.map(id=>{\n    const it=SHOP_ITEMS.find(i=>i.id===id);if(!it) return '';\n    const equipped=GS.cosmetics[it.cat]===id;\n    return `<div class=\"wd-cell ${equipped?'equipped':''}\" title=\"${it.name}\" onclick=\"equipItem('${id}')\">\n      ${it.icon}\n    </div>`;\n  }).join(''):'<p style=\"color:#555;font-size:10px;grid-column:1/-1;\">Sin objetos. Visita la tienda.</p>';\n  renderWardrobePreview();\n}\nfunction equipItem(id){\n  const it=SHOP_ITEMS.find(i=>i.id===id);if(!it) return;\n  if(GS.cosmetics[it.cat]===id) GS.cosmetics[it.cat]=null;\n  else GS.cosmetics[it.cat]=id;\n  if(GS.cosmetics.hat&&GS.cosmetics.skin&&GS.cosmetics.trail) SDK.unlock('meca_moda');\n  buildWardrobeUI();saveGame();\n}\nfunction unequipSlot(slot){\n  GS.cosmetics[slot]=null;buildWardrobeUI();\n}\nfunction renderWardrobePreview(){\n  const wc=document.getElementById('wd-canvas');\n  if(!wc) return;\n  const wctx=wc.getContext('2d');\n  wctx.clearRect(0,0,80,90);\n  wctx.fillStyle='rgba(0,60,120,0.4)';wctx.fillRect(0,0,80,90);\n  const skin=GS.cosmetics.skin?SKIN_TINTS[GS.cosmetics.skin]:null;\n  // Draw duck on preview canvas\n  wctx.save();\n  if(duckImg.complete&&duckImg.naturalWidth>0) wctx.drawImage(duckImg,22,30,36,36);\n  if(skin){wctx.globalCompositeOperation='source-atop';wctx.fillStyle=skin;wctx.fillRect(22,30,36,36);wctx.globalCompositeOperation='source-over';}\n  wctx.restore();\n  // Hat preview on mini canvas using main ctx temporarily\n  if(GS.cosmetics.hat){\n    // We draw hat using the main ctx's drawHat — redirect to preview canvas\n    const prevCtx=ctx;\n    // Can't easily redirect ctx, so use emoji fallback\n    const it=SHOP_ITEMS.find(i=>i.id===GS.cosmetics.hat);\n    if(it){wctx.font='22px serif';wctx.textAlign='center';wctx.textBaseline='middle';wctx.fillText(it.icon,40,18);}\n  }\n}\n\n/* ── GAME FLOW ── */\nfunction triggerGameOver(){\n  GS.running=false;GS.paused=false;stopTimer();\n  document.getElementById('go-stats').innerHTML=\n    'Estrellas: <b style=\"color:#f39c12\">'+GS.stars+'</b><br>Tiburones: <b style=\"color:#e74c3c\">'+GS.kills+\n    '</b><br>Retos: <b style=\"color:#4caf50\">'+GS.doneChallenges.size+'</b>/19<br>Dron: <b>'+\n    (GS.player.hasDrone?'Construido':'Sin construir')+'</b>';\n  document.getElementById('go-scr').classList.remove('hidden');\n}\nfunction newGame(){\n  if(loadSave()&&!confirm('¿Empezar de cero? Se borrará tu partida guardada.')) return;\n  try{localStorage.removeItem(SAVE_KEY);}catch(e){}\n  startCinematic();\n}\nfunction restartGame(){\n  document.getElementById('go-scr').classList.add('hidden');\n  GS.player={x:0,y:0,hp:100,dir:0,swordTimer:0,invTimer:0,hasDrone:false};\n  GS.kills=0;GS.stars=0;GS.doneChallenges=new Set();GS.inventory=[];\n  GS.sharks=[];GS.whales=[];GS.particles=[];GS.traps=[];GS.shieldActive=false;\n  GS.techs={central:false,volcano:false,mountain:false,swamp:false,clouds:false};\n  GS.cosmetics.owned=new Set();GS.cosmetics.hat=null;GS.cosmetics.skin=null;GS.cosmetics.trail=null;\n  droneAssembled={};GS.visited=new Set();GS.hardCount=0;\n  ISLANDS.forEach(i=>document.getElementById('ts-'+i.id)?.classList.remove('unlocked'));\n  startGame();\n}\nfunction showNotif(msg){\n  const n=document.getElementById('notif');n.textContent=msg;n.classList.add('show');\n  clearTimeout(n._t);n._t=setTimeout(()=>n.classList.remove('show'),3200);\n}\nlet last=0;\nfunction loop(ts){\n  const dt=Math.min((ts-last)/1000,0.05);last=ts;\n  if(GS.running&&!GS.paused){updatePlayer(dt);updateSharks(dt);updateWhales(dt);updateParticles(dt);detectIsland();}\n  render();\n  requestAnimationFrame(loop);\n}\nfunction startGame(){\n  document.getElementById('title-scr').classList.add('hidden');\n  GS.running=true;GS.paused=false;\n  GS.player.x=40*TILE+TILE/2;GS.player.y=30*TILE+TILE/2;\n  spawnSharks();spawnWhales();initChallenges();initDecor();updateHUD();\n  showNotif('Mecaquack listo — explora el archipielago!');\n  setTimeout(()=>showNotif('Islas nuevas al este y sur. Visita Mercaquack para la tienda.'),4000);\n}\n\n/* ── CINEMATIC SYSTEM ── */\nconst CIN_SLIDES=[\n  {img:cin1Img,text:'En el vasto océano, donde el sol pinta el horizonte de oro y los vientos llevan secretos de isla en isla, existe un archipiélago extraordinario. Un lugar donde la naturaleza y la ingeniería se entrelazan en perfecta armonía: el Archipiélago Mecaquack.'},\n  {img:cin2Img,text:'Al frente de esta parvada vivía Mecaquack, un pato ingeniero de corazón curioso y patas trabajadoras. Sus días transcurrían entre inventos, fórmulas y el suave murmullo de las olas — hasta que un amanecer rompió para siempre esa paz.'},\n  {img:cin3Img,text:'Sin previo aviso, los temidos Tiburones de Tierra emergieron de las profundidades. Con sus mandíbulas de acero arrasaron el archipiélago. La parvada quedó dispersada, los amigos capturados, los nidos destruidos. Mecaquack era el único que quedaba libre.'},\n  {img:cin4Img,text:'Mecaquack se levantó entre los escombros, tomó su llave inglesa y desplegó el mapa del archipiélago. Solo, pero no rendido. Con el conocimiento de la ingeniería como escudo y la valentía como motor, emprende la misión más importante de su vida: rescatar a todos.'}\n];\nlet _cinIdx=0,_cinTyping=null,_cinFull='';\n\nfunction startCinematic(){\n  document.getElementById('title-scr').classList.add('hidden');\n  document.getElementById('cin-scr').classList.remove('hidden');\n  _cinIdx=0;\n  _showCinSlide(0);\n}\nfunction _showCinSlide(idx){\n  clearTimeout(_cinTyping);\n  const slide=CIN_SLIDES[idx];\n  const img=document.getElementById('cin-img');\n  img.style.opacity='0';\n  setTimeout(()=>{img.src=slide.img.src;img.style.opacity='1';},80);\n  document.getElementById('cin-text').textContent='';\n  _cinFull=slide.text;\n  _typeWriter(slide.text,document.getElementById('cin-text'),0);\n  // progress dots\n  const dots=document.getElementById('cin-dots');\n  dots.innerHTML='';\n  CIN_SLIDES.forEach((_,i)=>{\n    const d=document.createElement('div');\n    d.style.cssText='width:9px;height:9px;border-radius:50%;transition:background .3s;background:'+(i===idx?'#f39c12':'#444')+';';\n    dots.appendChild(d);\n  });\n  const btn=document.getElementById('cin-next-btn');\n  btn.innerHTML=idx===CIN_SLIDES.length-1?'COMENZAR &#x1F3AE;':'SIGUIENTE &#x27A1;';\n}\nfunction _typeWriter(text,el,i){\n  if(i<=text.length){el.textContent=text.substring(0,i);_cinTyping=setTimeout(()=>_typeWriter(text,el,i+1),22);}\n}\nfunction cinNext(){\n  clearTimeout(_cinTyping);\n  const el=document.getElementById('cin-text');\n  if(el.textContent.length<_cinFull.length){el.textContent=_cinFull;return;}\n  if(_cinIdx<CIN_SLIDES.length-1){_cinIdx++;_showCinSlide(_cinIdx);}\n  else{skipCinematic();}\n}\nfunction skipCinematic(){\n  clearTimeout(_cinTyping);\n  document.getElementById('cin-scr').classList.add('hidden');\n  startGame();\n}\n\n/* ── BOSS FIGHT ── */\nfunction skipToBoss(){\n  document.getElementById('title-scr').classList.add('hidden');\n  bossPractice=true;bossFromWorld=false;\n  _openBossScreen();\n}\nfunction leaveBoss(){\n  document.getElementById('boss-scr').classList.add('hidden');\n  if(bossFromWorld){GS.running=true;GS.paused=false;}\n  else document.getElementById('title-scr').classList.remove('hidden');\n}\nfunction _openBossScreen(){\n  GS.running=false;\n  document.getElementById('boss-scr').classList.remove('hidden');\n  document.getElementById('boss-intro').style.display='';\n  document.getElementById('boss-fight').style.display='none';\n  document.getElementById('boss-dead').style.display='none';\n  document.getElementById('boss-img-full').src=bossFullImg.src;\n}\nconst BOSS_Q=[\n  {q:'¿Cuál es la Primera Ley de Newton (Ley de Inercia)?',\n   opts:['Un objeto en reposo permanece en reposo a menos que una fuerza neta actúe sobre él','La fuerza es igual a la masa por la aceleración','A toda acción corresponde una reacción igual y opuesta','La energía no se crea ni se destruye'],\n   ans:0,dmg:45,\n   dlg:'¡Ajá! ¿Sabes de física, pato ingeniero? ¡Demuéstramelo!'},\n  {q:'¿Cuál de estos materiales tiene mayor conductividad eléctrica?',\n   opts:['Plástico','Madera','Cobre','Vidrio'],\n   ans:2,dmg:45,\n   dlg:'Las propiedades de los materiales son clave para todo ingeniero. ¡Responde si puedes!'},\n  {q:'Circuito serie con R₁=10Ω y R₂=20Ω conectados a 30V. ¿Cuánta corriente fluye?',\n   opts:['0.5 A','1 A','3 A','2 A'],\n   ans:1,dmg:45,\n   dlg:'¡Circuitos! Aplica la Ley de Ohm correctamente... si te atreves.'},\n  {q:'¿Qué principio establece que la presión aplicada a un fluido confinado se transmite uniformemente en todas direcciones?',\n   opts:['Principio de Arquímedes','Ley de Bernoulli','Principio de Pascal','Ley de Hooke'],\n   ans:2,dmg:48,\n   dlg:'Los fluidos son mi elemento natural. ¿Y el tuyo, ingenieurillo?'},\n  {q:'¿Cuál es la fórmula del trabajo mecánico?',\n   opts:['W = m × g','W = F × d × cos(θ)','W = ½ × m × v²','W = P × t'],\n   ans:1,dmg:50,\n   dlg:'¡El trabajo! Veamos si puedes con esto, patito.'},\n  {q:'En un puente simplemente apoyado con carga puntual al centro, ¿dónde ocurren los esfuerzos máximos de flexión?',\n   opts:['En los apoyos','A un cuarto del vano','En el centro del vano','En los tercios del vano'],\n   ans:2,dmg:50,\n   dlg:'¡Estructuras! Aquí se separan los ingenieros de los impostores. ¡GRRR!'},\n  {q:'Una máquina recibe 500 J de energía y produce 350 J de trabajo útil. ¿Cuál es su eficiencia?',\n   opts:['35%','70%','85%','50%'],\n   ans:1,dmg:60,\n   dlg:'¡Última pregunta! Si respondes bien... habré sido derrotado. ¡IMPOSIBLE para un pato!'}\n];\nlet _bossState={playerHp:100,bossHp:300,qIdx:0,answered:false};\n\nfunction startBossFight(){\n  document.getElementById('boss-intro').style.display='none';\n  document.getElementById('boss-fight').style.display='';\n  document.getElementById('boss-img-small').src=bossSmallImg.src;\n  _bossState={playerHp:100,bossHp:300,qIdx:0,answered:false};\n  _renderBossQ();\n}\nfunction _renderBossQ(){\n  const q=BOSS_Q[_bossState.qIdx];\n  document.getElementById('boss-dialogue').textContent=q.dlg;\n  document.getElementById('boss-q').textContent=q.q;\n  document.getElementById('boss-qnum').textContent=_bossState.qIdx+1;\n  document.getElementById('boss-stars-live').textContent=GS?GS.stars:0;\n  document.getElementById('boss-result').textContent='';\n  const optsDiv=document.getElementById('boss-opts');\n  optsDiv.innerHTML='';\n  q.opts.forEach((opt,i)=>{\n    const btn=document.createElement('button');\n    btn.className='btn sec';\n    btn.style.cssText='font-size:11px;padding:7px 12px;text-align:left;width:100%;';\n    btn.textContent=['A','B','C','D'][i]+'. '+opt;\n    btn.onclick=()=>_bossPick(i);\n    optsDiv.appendChild(btn);\n  });\n  _bossState.answered=false;\n  _updateBossHUD();\n}\nfunction _bossPick(i){\n  if(_bossState.answered)return;\n  _bossState.answered=true;\n  const q=BOSS_Q[_bossState.qIdx];\n  const res=document.getElementById('boss-result');\n  document.getElementById('boss-opts').querySelectorAll('button').forEach((b,j)=>{\n    b.disabled=true;\n    if(j===q.ans)b.style.background='#1e8449';\n    else if(j===i&&i!==q.ans)b.style.background='#922b21';\n  });\n  if(i===q.ans){\n    _bossState.bossHp=Math.max(0,_bossState.bossHp-q.dmg);\n    res.innerHTML='<span style=\"color:#4caf50\">&#x2714; ¡CORRECTO! Bombón recibe -'+q.dmg+' HP</span>';\n    if(GS)addStars(3);\n  }else{\n    _bossState.playerHp=Math.max(0,_bossState.playerHp-25);\n    res.innerHTML='<span style=\"color:#e74c3c\">&#x2718; Incorrecto — pierdes 25 HP</span>';\n  }\n  _updateBossHUD();\n  setTimeout(()=>{\n    if(_bossState.bossHp<=0){_bossDies();}\n    else if(_bossState.playerHp<=0){_bossWins();}\n    else{\n      _bossState.qIdx++;\n      if(_bossState.qIdx>=BOSS_Q.length)_bossDies();\n      else _renderBossQ();\n    }\n  },1800);\n}\nfunction _updateBossHUD(){\n  document.getElementById('boss-player-hp').textContent=_bossState.playerHp;\n  document.getElementById('boss-hp').textContent=_bossState.bossHp;\n  document.getElementById('boss-phbar').style.width=_bossState.playerHp+'%';\n  document.getElementById('boss-hbar').style.width=(_bossState.bossHp/300*100)+'%';\n}\nfunction _bossDies(){\n  document.getElementById('boss-fight').style.display='none';\n  document.getElementById('boss-dead').style.display='';\n  if(GS)addStars(20);\n  if(!bossPractice){\n    SDK.unlock('meca_bombon');\n    if(_bossState.playerHp>=100) SDK.unlock('meca_perfecto');\n    GS.bossDefeated=true;saveGame();\n  } else if(typeof showNotif==='function') showNotif('Modo práctica: vence a Bombón en su guarida para el logro');\n  if(typeof showNotif==='function')showNotif('¡Bombón derrotado! +20 ⭐');\n}\nfunction _bossWins(){\n  document.getElementById('boss-dialogue').textContent='¡JA JA JA! ¡Fracasaste! ¡El archipiélago es mío!';\n  document.getElementById('boss-result').innerHTML='<span style=\"color:#e74c3c\">&#x1F480; Bombón gana esta ronda... intenta de nuevo.</span>';\n  setTimeout(()=>{\n    document.getElementById('boss-fight').style.display='none';\n    document.getElementById('boss-intro').style.display='';\n  },3000);\n}\n\n/* ── CREDITS ── */\nlet _credAnim=null;\nfunction showCredits(){\n  document.getElementById('boss-scr').classList.add('hidden');\n  const scr=document.getElementById('credits-scr');\n  scr.classList.remove('hidden');\n  // star canvas\n  const cvs=document.getElementById('credits-stars-canvas');\n  cvs.width=window.innerWidth;cvs.height=window.innerHeight;\n  const cx=cvs.getContext('2d');\n  const stars=Array.from({length:120},()=>({x:Math.random()*cvs.width,y:Math.random()*cvs.height,r:Math.random()*1.5+.5,a:Math.random()}));\n  function drawStars(){if(!scr.classList.contains('hidden')){cx.clearRect(0,0,cvs.width,cvs.height);stars.forEach(s=>{s.a+=.005*(Math.random()>.5?1:-1);s.a=Math.max(.1,Math.min(1,s.a));cx.globalAlpha=s.a;cx.fillStyle='#fff';cx.beginPath();cx.arc(s.x,s.y,s.r,0,6.28);cx.fill();});cx.globalAlpha=1;requestAnimationFrame(drawStars);}}\n  drawStars();\n  const roll=document.getElementById('credits-roll');\n  roll.style.top='100%';\n  let pos=100;\n  clearInterval(_credAnim);\n  _credAnim=setInterval(()=>{\n    pos-=.35;\n    roll.style.top=pos+'%';\n    const bh=roll.getBoundingClientRect().height;\n    if(pos<-(bh/window.innerHeight*100+10))creditsEnd();\n  },16);\n}\nfunction creditsEnd(){\n  clearInterval(_credAnim);\n  document.getElementById('credits-scr').classList.add('hidden');\n  document.getElementById('title-scr').classList.remove('hidden');\n}\n\n\n/* ── PAUSA (Esc / P) ── */\nfunction anyOverlayOpen(){return [...document.querySelectorAll('.ov')].some(o=>!o.classList.contains('hidden')&&o.id!=='pause-scr');}\nfunction togglePause(){\n  if(!GS.running) return;\n  const p=document.getElementById('pause-scr');\n  if(p.classList.contains('hidden')){if(anyOverlayOpen()) return;GS.paused=true;p.classList.remove('hidden');saveGame();}\n  else{p.classList.add('hidden');GS.paused=false;}\n}\nwindow.addEventListener('keydown',e=>{if(e.code==='Escape'||e.code==='KeyP') togglePause();});\nsetInterval(()=>{if(GS.running&&!GS.paused) saveGame();},10000);\n\n/* ── CONTROLES TÁCTILES ── */\n(function(){\n  if(!('ontouchstart' in window)&&!(navigator.maxTouchPoints>0)) return;\n  document.body.classList.add('touch');\n  const joy=document.getElementById('joy'),knob=document.getElementById('joy-knob');\n  let jid=null,cx0=0,cy0=0;\n  const setKeys=(dx,dy)=>{GS.keys.KeyA=dx<-0.35;GS.keys.KeyD=dx>0.35;GS.keys.KeyW=dy<-0.35;GS.keys.KeyS=dy>0.35;};\n  joy.addEventListener('pointerdown',e=>{jid=e.pointerId;const r=joy.getBoundingClientRect();cx0=r.left+r.width/2;cy0=r.top+r.height/2;joy.setPointerCapture(jid);move(e);});\n  const move=e=>{if(e.pointerId!==jid) return;let dx=(e.clientX-cx0)/50,dy=(e.clientY-cy0)/50;const m=Math.hypot(dx,dy);if(m>1){dx/=m;dy/=m;}\n    knob.style.transform=`translate(${dx*40}px,${dy*40}px)`;setKeys(dx,dy);};\n  joy.addEventListener('pointermove',move);\n  const end=e=>{if(e.pointerId!==jid) return;jid=null;knob.style.transform='';setKeys(0,0);};\n  joy.addEventListener('pointerup',end);joy.addEventListener('pointercancel',end);\n  document.querySelectorAll('[data-tk]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();\n    const k=b.dataset.tk;\n    if(k==='sword') tryAttack(); else if(k==='use') tryInteract(); else if(k==='drone') toggleDrone(); else if(k==='wd') toggleWardrobe(); else if(k==='pause') togglePause();}));\n  Object.entries(TECH_DEF).forEach(([id,tech])=>{const el=document.getElementById('ts-'+id);if(el) el.addEventListener('pointerdown',()=>{if(GS.techs[id]&&GS.running&&!GS.paused) tech.act();});});\n})();\nif(loadSave()) document.getElementById('btn-continue').style.display='';\n\nrequestAnimationFrame(loop);\n\n</script>\n</body>\n</html>"} });
